Object.assign(window.SB_FEED_BODY, {"pl-stage":{"src":"act:stage","route":"#/atlas/honey/stage","cta":"Open the Big Stage","title":"Act IX · The Big Stage","body":"15 stops on this road, from “Ego & Self — ego / auto / alter” to “Championship Loanword Patterns — Rare Languages”."},"li-u114":{"src":"concept:11:concept","route":"#/stop/u114","cta":"Open this stop","title":"Ego & Self — ego / auto / alter","body":"Words built on Latin ego = I and Greek autos = self describe how people relate to themselves. Master this cluster and you unlock personality vocabulary from egotist to autodidact."},"lc-u114-0":{"src":"concept:11:cards:0","route":"#/stop/u114","cta":"Open this stop","title":"Ego & Self — ego / auto / alter · The Core","body":"Ego = Latin \"I.\" An egoist cares only about themselves. An egotist constantly talks about themselves — the extra t stands for talking. Both from ego; only the suffix differs."},"lc-u114-1":{"src":"concept:11:cards:1","route":"#/stop/u114","cta":"Open this stop","title":"Ego & Self — ego / auto / alter · Scaling Up","body":"An egocentric (ego + centrum = center) believes the universe revolves around them. An egomaniac (ego + Greek mania = madness) takes self-obsession to a pathological extreme."},"lc-u114-2":{"src":"concept:11:cards:2","route":"#/stop/u114","cta":"Open this stop","title":"Ego & Self — ego / auto / alter · The Opposite — alter","body":"Latin alter = other. Altruistic = puts others first. Magnanimous (magna = great + animus = soul) = great-souled generosity. Philanthropist (philos = love + anthropos = human) = lover of humanity."},"lc-u114-3":{"src":"concept:11:cards:3","route":"#/stop/u114","cta":"Open this stop","title":"Ego & Self — ego / auto / alter · auto- (Greek self)","body":"Autobiography = writes own life. Autodidact (auto- + didaskein = teach) = self-taught. Autonomous = self-governing. Autocracy = rule by one alone. When you see auto-, think \"by itself/by oneself.\""},"lc-u114-4":{"src":"concept:11:cards:4","route":"#/stop/u114","cta":"Open this stop","title":"Ego & Self — ego / auto / alter · Bee Traps","body":"Egoism (philosophy of self-interest) ≠ egotism (excessive self-talk). Narcissism has double-s from Greek name Narcissus. Solipsism (solus = alone + ipse = self) = only the self exists — rare root, common bee word."},"uq-u114-0":{"src":"unit:u114:qs:0","route":"#/stop/u114","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Ego & Self — ego / auto / alter”?","opts":["Words built on Latin ego = I and Greek autos = self describe how people relate to themselves.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Ego & Self — ego / auto / alter”."}},"uq-u114-3":{"src":"unit:u114:qs:3","route":"#/stop/u114","cta":"Open this stop","title":"Whose hook?","play":{"q":"“An EGO+IST is one who practices putting the EGO first — the artist of self-interest.” — which word is this hook about?","opts":["egoist","egotist","egocentric","egomaniac"],"after":"From “Ego & Self — ego / auto / alter”."}},"wd-egoist":{"src":"concept:11:words:0:def","route":"#/word/egoist","cta":"Open the word card","title":"egoist","roman":"EE-goh-ist","body":"a conceited and self-centered person","clip":1},"wx-egoist":{"src":"concept:11:words:0:ex","route":"#/word/egoist","cta":"Open the word card","title":"In a sentence · egoist","body":"The notorious egoist never once asked how his teammates were feeling after the loss.","clip":1},"wh-egoist":{"src":"concept:11:words:0:hook","route":"#/word/egoist","cta":"Open the word card","title":"Remember it · egoist","body":"An EGO+IST is one who practices putting the EGO first — the artist of self-interest."},"wo-egoist":{"src":"lore:egoist:0","route":"#/word/egoist","cta":"Open the word card","title":"Where it comes from · egoist","body":"Latin ego (I) + -ist — a person all about 'I.'"},"wx-egotist":{"src":"concept:11:words:1:ex","route":"#/word/egotist","cta":"Open the word card","title":"In a sentence · egotist","body":"The egotist spent the entire dinner talking about himself without asking a single question.","clip":1},"wh-egotist":{"src":"concept:11:words:1:hook","route":"#/word/egotist","cta":"Open the word card","title":"Remember it · egotist","body":"An EGO+T+IST talks about themselves constantly — the T stands for 'Talks about himself incessantly.'"},"wd-egocentric":{"src":"concept:11:words:2:def","route":"#/word/egocentric","cta":"Open the word card","title":"egocentric","roman":"ee-goh-SEH-ntrihk","body":"a self-centered person with little regard for others","clip":1},"wx-egocentric":{"src":"concept:11:words:2:ex","route":"#/word/egocentric","cta":"Open the word card","title":"In a sentence · egocentric","body":"The egocentric team captain always took credit for victories but blamed teammates for every loss.","clip":1},"wh-egocentric":{"src":"concept:11:words:2:hook","route":"#/word/egocentric","cta":"Open the word card","title":"Remember it · egocentric","body":"An EGO-CENTRIC person puts their EGO at the CENTER of everything — ego+center+ic."},"wo-egocentric":{"src":"lore:egocentric:0","route":"#/word/egocentric","cta":"Open the word card","title":"Where it comes from · egocentric","body":"Latin ego = I + centrum = center"},"wd-egomaniac":{"src":"concept:11:words:3:def","route":"#/word/egomaniac","cta":"Open the word card","title":"egomaniac","roman":"ee-goh-MAY-nee-ak","body":"an abnormally egotistical person","clip":1},"wx-egomaniac":{"src":"concept:11:words:3:ex","route":"#/word/egomaniac","cta":"Open the word card","title":"In a sentence · egomaniac","body":"The class president was such an egomaniac that he insisted every school project be named after him.","clip":1},"wh-egomaniac":{"src":"concept:11:words:3:hook","route":"#/word/egomaniac","cta":"Open the word card","title":"Remember it · egomaniac","body":"An EGO+MANIA+C is a maniac whose obsession is their own ego — spot the MANIA in the middle."},"wo-egomaniac":{"src":"lore:egomaniac:0","route":"#/word/egomaniac","cta":"Open the word card","title":"Where it comes from · egomaniac","body":"Latin ego = I + Greek mania = madness + -ac = one afflicted"},"wd-altruistic":{"src":"concept:11:words:4:def","route":"#/word/altruistic","cta":"Open the word card","title":"altruistic","roman":"aw-ltroo-IH-stihk","body":"showing unselfish concern for the welfare of others","clip":1},"wx-altruistic":{"src":"concept:11:words:4:ex","route":"#/word/altruistic","cta":"Open the word card","title":"In a sentence · altruistic","body":"Her altruistic decision to donate her entire prize money to the shelter inspired everyone in town.","clip":1},"wh-altruistic":{"src":"concept:11:words:4:hook","route":"#/word/altruistic","cta":"Open the word card","title":"Remember it · altruistic","body":"ALTRUISTIC people are TRUE to others — no sneaky extra 'i': A-L-T-R-U-I-S-T-I-C, ten clean letters."},"wd-magnanimous":{"src":"concept:11:words:5:def","route":"#/word/magnanimous","cta":"Open the word card","title":"magnanimous","roman":"m-a-g-n-A-n-uh-m-uh-s","body":"is generous in forgiving insult or injury","clip":1},"wx-magnanimous":{"src":"concept:11:words:5:ex","route":"#/word/magnanimous","cta":"Open the word card","title":"In a sentence · magnanimous","body":"Though he lost the chess final, Arjun was magnanimous and praised his rival's clever opening.","clip":1},"wh-magnanimous":{"src":"concept:11:words:5:hook","route":"#/word/magnanimous","cta":"Open the word card","title":"Remember it · magnanimous","body":"A magnANIMous person has a GREAT ANIMAL spirit — big-souled and forgiving."},"wo-magnanimous":{"src":"lore:magnanimous:0","route":"#/word/magnanimous","cta":"Open the word card","title":"Where it comes from · magnanimous","body":"Latin magnus = great + animus = spirit/soul"},"wd-autonomous":{"src":"concept:11:words:8:def","route":"#/word/autonomous","cta":"Open the word card","title":"autonomous","roman":"aw-TAH-nuh-muhs","body":"(of political bodies) not controlled by outside forces","clip":1},"wx-autonomous":{"src":"concept:11:words:8:ex","route":"#/word/autonomous","cta":"Open the word card","title":"In a sentence · autonomous","body":"an autonomous judiciary","clip":1},"wh-autonomous":{"src":"concept:11:words:8:hook","route":"#/word/autonomous","cta":"Open the word card","title":"Remember it · autonomous","body":"An autoNOMous region makes its own NORMS — spell NOM then add -ous, not just -us."},"wd-egotism":{"src":"concept:11:words:11:def","route":"#/word/egotism","cta":"Open the word card","title":"egotism","roman":"EE-guh-tih-zuhm","body":"an exaggerated opinion of your own importance","clip":1},"wx-egotism":{"src":"concept:11:words:11:ex","route":"#/word/egotism","cta":"Open the word card","title":"In a sentence · egotism","body":"His egotism was exhausting; every conversation somehow circled back to his own accomplishments.","clip":1},"wh-egotism":{"src":"concept:11:words:11:hook","route":"#/word/egotism","cta":"Open the word card","title":"Remember it · egotism","body":"EGO+T+ISM — the extra T stands for 'Talking about myself' — egotism has a T that egoism lacks."},"wo-egotism":{"src":"lore:egotism:0","route":"#/word/egotism","cta":"Open the word card","title":"Where it comes from · egotism","body":"Latin ego = I + -t- (inserted) + -ism = doctrine"},"wd-egoism":{"src":"concept:11:words:12:def","route":"#/word/egoism","cta":"Open the word card","title":"egoism","roman":"EE-goh-ih-zuhm","body":"(ethics) the theory that the pursuit of your own welfare in the basis of morality","clip":1},"wx-egoism":{"src":"concept:11:words:12:ex","route":"#/word/egoism","cta":"Open the word card","title":"In a sentence · egoism","body":"The philosophy teacher challenged her students to debate whether egoism could ever lead to a just society.","clip":1},"wh-egoism":{"src":"concept:11:words:12:hook","route":"#/word/egoism","cta":"Open the word card","title":"Remember it · egoism","body":"EGOISM is the doctrine (ISM) that the great 'I' (EGO) comes first — ego+ism."},"wo-egoism":{"src":"lore:egoism:0","route":"#/word/egoism","cta":"Open the word card","title":"Where it comes from · egoism","body":"Latin ego = I + -ism = doctrine or belief"},"li-u115":{"src":"concept:12:concept","route":"#/stop/u115","cta":"Open this stop","title":"Talking & Speaking — loqu / phon / verb","body":"Latin loqui = to speak and Greek phonē = sound/voice are two of the most productive roots in English. Together they explain dozens of words about how, how much, and how well people communicate."},"lc-u115-0":{"src":"concept:12:cards:0","route":"#/stop/u115","cta":"Open this stop","title":"Talking & Speaking — loqu / phon / verb · The loqu- Root","body":"Latin loqui = to speak. Loquacious = talks too freely. Eloquent = speaks beautifully (e- = out, so speaking out well). Grandiloquent = pompously grand speech. Ventriloquist (ventri = belly) = speaks from the belly."},"lc-u115-1":{"src":"concept:12:cards:1","route":"#/stop/u115","cta":"Open this stop","title":"Talking & Speaking — loqu / phon / verb · Silence vs Talk Scale","body":"Taciturn (Latin tacere = silent) = habitually quiet. Reticent = reluctant to speak. Laconic (from Sparta) = brief and to-the-point. Verbose (verbum = word) = uses too many words. Garrulous = excessively chatty."},"lc-u115-2":{"src":"concept:12:cards:2","route":"#/stop/u115","cta":"Open this stop","title":"Talking & Speaking — loqu / phon / verb · loqu- Word Families","body":"Soliloquy (solo + loquy) = talking to yourself on stage. Colloquy (col- + loquy) = formal two-way conversation. Colloquial = everyday spoken language. Obloquy (ob- against) = harsh public criticism. Interlocutor = the person you are speaking with."},"lc-u115-3":{"src":"concept:12:cards:3","route":"#/stop/u115","cta":"Open this stop","title":"Talking & Speaking — loqu / phon / verb · The phon- Family (Greek)","body":"phonē = sound/voice. Always spelled ph not f — the Greek signal. Cacophony (kakos = bad) = harsh noise. Euphony (eu = good) = pleasant sound. Symphony (sym = together) = harmonious sounds. Polyphony (poly = many) = many simultaneous voices."},"lc-u115-4":{"src":"concept:12:cards:4","route":"#/stop/u115","cta":"Open this stop","title":"Talking & Speaking — loqu / phon / verb · High-Value Bee Words","body":"Magniloquent = inflated boastful speech. Pauciloquent (pauci = few) = using very few words. Somniloquy (somni = sleep) = talking in one's sleep. These long compounds decode instantly if you know -loqu-."},"uq-u115-0":{"src":"unit:u115:qs:0","route":"#/stop/u115","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Talking & Speaking — loqu / phon / verb”?","opts":["Latin loqui = to speak and Greek phonē = sound/voice are two of the most productive roots in English.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Talking & Speaking — loqu / phon / verb”."}},"uq-u115-3":{"src":"unit:u115:qs:3","route":"#/stop/u115","cta":"Open this stop","title":"Whose hook?","play":{"q":"“A ▁▁▁ person SQUAWKS like a parrot — ▁▁▁” — which word is this hook about?","opts":["loquacious","eloquent","grandiloquent","ventriloquist"],"after":"From “Talking & Speaking — loqu / phon / verb”."}},"wd-loquacious":{"src":"concept:12:words:0:def","route":"#/word/loquacious","cta":"Open the word card","title":"loquacious","roman":"l-oh-k-w-AY-sh-uh-s","body":"is talking or tending to talk too freely","clip":1},"wx-loquacious":{"src":"concept:12:words:0:ex","route":"#/word/loquacious","cta":"Open the word card","title":"In a sentence · loquacious","body":"Our loquacious tour guide chattered happily about every single brick in the castle wall.","clip":1},"wh-loquacious":{"src":"concept:12:words:0:hook","route":"#/word/loquacious","cta":"Open the word card","title":"Remember it · loquacious","body":"A loquacious person SQUAWKS like a parrot — loquACIOUS"},"wo-loquacious":{"src":"lore:loquacious:0","route":"#/word/loquacious","cta":"Open the word card","title":"Where it comes from · loquacious","body":"Latin loqui = to speak"},"wd-grandiloquent":{"src":"concept:12:words:2:def","route":"#/word/grandiloquent","cta":"Open the word card","title":"grandiloquent","roman":"gra-NDIH-luh-kwuhnt","body":"lofty in style","clip":1},"wx-grandiloquent":{"src":"concept:12:words:2:ex","route":"#/word/grandiloquent","cta":"Open the word card","title":"In a sentence · grandiloquent","body":"In grandiloquent language the mayor called our muddy village pond a shimmering silver lake.","clip":1},"wh-grandiloquent":{"src":"concept:12:words:2:hook","route":"#/word/grandiloquent","cta":"Open the word card","title":"Remember it · grandiloquent","body":"GRANDI-LO-QUENT rhymes with eloquent — a grandiloquent speaker is an eloquent speaker gone grand and pompous."},"wo-grandiloquent":{"src":"lore:grandiloquent:0","route":"#/word/grandiloquent","cta":"Open the word card","title":"Where it comes from · grandiloquent","body":"Latin grandiloquus = speaking grandly (grandis=great + loqui=to speak)"},"wd-colloquial":{"src":"concept:12:words:6:def","route":"#/word/colloquial","cta":"Open the word card","title":"colloquial","roman":"kuh-LOH-kwee-uhl","body":"characteristic of informal spoken language or conversation","clip":1},"wx-colloquial":{"src":"concept:12:words:6:ex","route":"#/word/colloquial","cta":"Open the word card","title":"In a sentence · colloquial","body":"wrote her letters in a colloquial style","clip":1},"wh-colloquial":{"src":"concept:12:words:6:hook","route":"#/word/colloquial","cta":"Open the word card","title":"Remember it · colloquial","body":"COLLOQUIAL speech is how people TALK together — double L, double the chatter."},"wd-obloquy":{"src":"concept:12:words:7:def","route":"#/word/obloquy","cta":"Open the word card","title":"obloquy","roman":"AW-bluh-kwee","body":"is abusive language aimed at a person","clip":1},"wx-obloquy":{"src":"concept:12:words:7:ex","route":"#/word/obloquy","cta":"Open the word card","title":"In a sentence · obloquy","body":"After betraying his teammates, the captain faced obloquy from fans throughout the entire city.","clip":1},"wh-obloquy":{"src":"concept:12:words:7:hook","route":"#/word/obloquy","cta":"Open the word card","title":"Remember it · obloquy","body":"OBLOQUy — people LOQUACIOUSLY speak AGAINST (ob) you."},"wo-obloquy":{"src":"lore:obloquy:0","route":"#/word/obloquy","cta":"Open the word card","title":"Where it comes from · obloquy","body":"Latin ob- = against + loqui = to speak"},"wd-interlocutor":{"src":"concept:12:words:8:def","route":"#/word/interlocutor","cta":"Open the word card","title":"interlocutor","roman":"ih-nter-LAH-kyuh-ter","body":"the performer in the middle of a minstrel line who engages the others in talk","clip":1},"wx-interlocutor":{"src":"concept:12:words:8:ex","route":"#/word/interlocutor","cta":"Open the word card","title":"In a sentence · interlocutor","body":"During the roundtable debate, the teacher acted as interlocutor, drawing out each student's argument in turn.","clip":1},"wh-interlocutor":{"src":"concept:12:words:8:hook","route":"#/word/interlocutor","cta":"Open the word card","title":"Remember it · interlocutor","body":"An interlocutor LOCUTES (speaks) BETWEEN people."},"wo-interlocutor":{"src":"lore:interlocutor:0","route":"#/word/interlocutor","cta":"Open the word card","title":"Where it comes from · interlocutor","body":"Latin interlocutor, from interloqui = to speak between, from inter-(between)+loqui(to speak)"},"wd-taciturn":{"src":"concept:12:words:9:def","route":"#/word/taciturn","cta":"Open the word card","title":"taciturn","roman":"t-A-s-ih-t-ur-n","body":"means inclined to silence","clip":1},"wx-taciturn":{"src":"concept:12:words:9:ex","route":"#/word/taciturn","cta":"Open the word card","title":"In a sentence · taciturn","body":"The taciturn new student rarely spoke in class, but her written essays were bold and full of ideas.","clip":1},"wh-taciturn":{"src":"concept:12:words:9:hook","route":"#/word/taciturn","cta":"Open the word card","title":"Remember it · taciturn","body":"TACITURN: someone TACIT and STERN who never speaks turns away in silence"},"wo-taciturn":{"src":"lore:taciturn:0","route":"#/word/taciturn","cta":"Open the word card","title":"Where it comes from · taciturn","body":"Latin taciturnus, from tacitus = silent, from tacere(to be silent)"},"wd-reticent":{"src":"concept:12:words:10:def","route":"#/word/reticent","cta":"Open the word card","title":"reticent","roman":"r-EH-t-ih-s-uh-n-t","body":"is someone disposed to be silent or not to speak freely","clip":1},"wx-reticent":{"src":"concept:12:words:10:ex","route":"#/word/reticent","cta":"Open the word card","title":"In a sentence · reticent","body":"Although she knew the answer, the reticent girl sat quietly and let the others debate for several minutes.","clip":1},"wh-reticent":{"src":"concept:12:words:10:hook","route":"#/word/reticent","cta":"Open the word card","title":"Remember it · reticent","body":"A RETICENT person is not reTICkEt — spell it with -ENT like SILENT, because silence is their talent."},"wo-reticent":{"src":"lore:reticent:0","route":"#/word/reticent","cta":"Open the word card","title":"Where it comes from · reticent","body":"Latin reticere = to keep silent"},"wd-verbose":{"src":"concept:12:words:11:def","route":"#/word/verbose","cta":"Open the word card","title":"verbose","roman":"ver-BOHS","body":"using or containing too many words","clip":1},"wx-verbose":{"src":"concept:12:words:11:ex","route":"#/word/verbose","cta":"Open the word card","title":"In a sentence · verbose","body":"His verbose essay took three whole pages to say what one paragraph could.","clip":1},"wh-verbose":{"src":"concept:12:words:11:hook","route":"#/word/verbose","cta":"Open the word card","title":"Remember it · verbose","body":"VERBOSE ends in '-ose' like 'grandiose' — a verbose person is grandiose with words."},"wd-garrulous":{"src":"concept:12:words:12:def","route":"#/word/garrulous","cta":"Open the word card","title":"garrulous","roman":"GEH-ruh-luhs","body":"full of trivial conversation","clip":1},"wx-garrulous":{"src":"concept:12:words:12:ex","route":"#/word/garrulous","cta":"Open the word card","title":"In a sentence · garrulous","body":"The garrulous tour guide talked nonstop for two hours, sharing every detail about each painting until the visitors were exhausted.","clip":1},"wh-garrulous":{"src":"concept:12:words:12:hook","route":"#/word/garrulous","cta":"Open the word card","title":"Remember it · garrulous","body":"GARRULous people GARGLE with words"},"wo-garrulous":{"src":"lore:garrulous:0","route":"#/word/garrulous","cta":"Open the word card","title":"Where it comes from · garrulous","body":"Latin garrulus = chattering, from garrire = to chatter"},"li-u116":{"src":"concept:13:concept","route":"#/stop/u116","cta":"Open this stop","title":"Honesty & Deception — ver / mendax / cred / pseudo","body":"Latin veritas = truth and mendax = lying create perfectly opposite word families. Greek pseudos = false adds a third. These cover the full honesty spectrum and appear frequently in spelling bees."},"lc-u116-0":{"src":"concept:13:cards:0","route":"#/stop/u116","cta":"Open this stop","title":"Honesty & Deception — ver / mendax / cred / pseudo · The Truth Root — ver-","body":"Latin veritas = truth. Veracious = truthful (≠ voracious = greedy!). Veracity = habitual truthfulness. Verify = prove true. Verdict (ver + dict = say) = what is truly stated. Aver = firmly declare as true. Verisimilitude = the appearance of truth."},"lc-u116-1":{"src":"concept:13:cards:1","route":"#/stop/u116","cta":"Open this stop","title":"Honesty & Deception — ver / mendax / cred / pseudo · The Lying Root — mendax","body":"Mendacious = habitually untruthful. Mendacity = the habit of lying. Memory trick: a mendacious person mends (bends) the truth. This root is rare in English — which is exactly why it keeps appearing in bees."},"lc-u116-2":{"src":"concept:13:cards:2","route":"#/stop/u116","cta":"Open this stop","title":"Honesty & Deception — ver / mendax / cred / pseudo · Deception Words","body":"Duplicitous (duplex = double) = two-faced. Dissemble = conceal true feelings. Prevaricate = speak evasively. Equivocate (equi = equal + voc = voice) = use deliberately ambiguous language. Disingenuous = not candid, pretending to be naïve."},"lc-u116-3":{"src":"concept:13:cards:3","route":"#/stop/u116","cta":"Open this stop","title":"Honesty & Deception — ver / mendax / cred / pseudo · The cred- Family — Believing","body":"Latin credere = to believe. Credulous = too easily believing. Incredulous = refusing to believe. Credibility = worthiness of belief. Miscreant (mis- + credere = believe wrongly) = a villain. Discredit = remove credibility."},"lc-u116-4":{"src":"concept:13:cards:4","route":"#/stop/u116","cta":"Open this stop","title":"Honesty & Deception — ver / mendax / cred / pseudo · pseudo- (Greek false)","body":"Greek pseudos = false. Pseudonym (pseudo- + onoma = name) = false name. Pseudoscience = fake science. ⚠️ Pseudo- begins with a SILENT p — P-S-E-U-D-O. The ps- cluster is a Greek signal; say /SOO-doh/ but spell P-S."},"uq-u116-0":{"src":"unit:u116:qs:0","route":"#/stop/u116","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Honesty & Deception — ver / mendax / cred / pseudo”?","opts":["Latin veritas = truth and mendax = lying create perfectly opposite word families.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Honesty & Deception — ver / mendax / cred / pseudo”."}},"uq-u116-3":{"src":"unit:u116:qs:3","route":"#/stop/u116","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁: VERy ACcurate = truth” — which word is this hook about?","opts":["veracity","veracious","verify","verdict"],"after":"From “Honesty & Deception — ver / mendax / cred / pseudo”."}},"wd-veracity":{"src":"concept:13:words:1:def","route":"#/word/veracity","cta":"Open the word card","title":"veracity","roman":"ver-A-sih-tee","body":"unwillingness to tell lies","clip":1},"wx-veracity":{"src":"concept:13:words:1:ex","route":"#/word/veracity","cta":"Open the word card","title":"In a sentence · veracity","body":"The judge praised the witness for her veracity, noting that every detail she provided matched the evidence exactly.","clip":1},"wh-veracity":{"src":"concept:13:words:1:hook","route":"#/word/veracity","cta":"Open the word card","title":"Remember it · veracity","body":"VERACity: VERy ACcurate = truth"},"wo-veracity":{"src":"lore:veracity:0","route":"#/word/veracity","cta":"Open the word card","title":"Where it comes from · veracity","body":"Latin verax = truthful, from verus = true"},"wd-verify":{"src":"concept:13:words:2:def","route":"#/word/verify","cta":"Open the word card","title":"verify","roman":"VEH-ruh-feye","body":"confirm the truth of","clip":1},"wx-verify":{"src":"concept:13:words:2:ex","route":"#/word/verify","cta":"Open the word card","title":"In a sentence · verify","body":"Please verify that the doors are closed","clip":1},"wh-verify":{"src":"concept:13:words:2:hook","route":"#/word/verify","cta":"Open the word card","title":"Remember it · verify","body":"VERIFY starts with VERI — VERy Important to spell it with an E, not an A!"},"wo-verify":{"src":"lore:verify:0","route":"#/word/verify","cta":"Open the word card","title":"Where it comes from · verify","body":"Latin verus, 'true' + facere, 'to make' — to make sure it's true."},"wd-verisimilitude":{"src":"concept:13:words:4:def","route":"#/word/verisimilitude","cta":"Open the word card","title":"verisimilitude","roman":"v-eh-r-uh-s-uh-m-IH-l-uh-t-oo-d","body":"the appearance of truth; the quality of seeming to be true","clip":1},"wx-verisimilitude":{"src":"concept:13:words:4:ex","route":"#/word/verisimilitude","cta":"Open the word card","title":"In a sentence · verisimilitude","body":"The novelist researched Medieval armor for months to give her fantasy story enough verisimilitude that readers would forget they were reading fiction.","clip":1},"wh-verisimilitude":{"src":"concept:13:words:4:hook","route":"#/word/verisimilitude","cta":"Open the word card","title":"Remember it · verisimilitude","body":"VERI (very true) + SIMILAR: something so similar to truth it seems real"},"wo-verisimilitude":{"src":"lore:verisimilitude:0","route":"#/word/verisimilitude","cta":"Open the word card","title":"Where it comes from · verisimilitude","body":"Latin verus=true + similis=like/similar"},"wd-mendacious":{"src":"concept:13:words:5:def","route":"#/word/mendacious","cta":"Open the word card","title":"mendacious","roman":"m-eh-n-d-AY-sh-uh-s","body":"is telling lies especially habitually","clip":1},"wx-mendacious":{"src":"concept:13:words:5:ex","route":"#/word/mendacious","cta":"Open the word card","title":"In a sentence · mendacious","body":"The mendacious salesman promised that the ancient car had never broken down, but the thick stack of repair receipts stuffed under the seat told a completely different and far more honest story.","clip":1},"wh-mendacious":{"src":"concept:13:words:5:hook","route":"#/word/mendacious","cta":"Open the word card","title":"Remember it · mendacious","body":"MENDACious — you can't MEND a liar's ways; -acious not -atious"},"wo-mendacious":{"src":"lore:mendacious:0","route":"#/word/mendacious","cta":"Open the word card","title":"Where it comes from · mendacious","body":"Latin mendax = lying, from mendum = fault, defect"},"wd-duplicitous":{"src":"concept:13:words:7:def","route":"#/word/duplicitous","cta":"Open the word card","title":"duplicitous","roman":"doo-PLIH-sih-tuhs","body":"deliberately deceptive, pretending to feel one way while secretly acting another","clip":1},"wx-duplicitous":{"src":"concept:13:words:7:ex","route":"#/word/duplicitous","cta":"Open the word card","title":"In a sentence · duplicitous","body":"Smiling at Nina while spreading rumours about her was a duplicitous thing to do.","clip":1},"wh-duplicitous":{"src":"concept:13:words:7:hook","route":"#/word/duplicitous","cta":"Open the word card","title":"Remember it · duplicitous","body":"A DUPLICITOUS person has a double face — no extra I after DUPLIC, just -ITOUS."},"wo-duplicitous":{"src":"lore:duplicitous:0","route":"#/word/duplicitous","cta":"Open the word card","title":"Where it comes from · duplicitous","body":"Latin duplicitas = doubleness, from duplex = twofold"},"wx-equivocate":{"src":"concept:13:words:10:ex","route":"#/word/equivocate","cta":"Open the word card","title":"In a sentence · equivocate","body":"The politician continued to equivocate when reporters pressed him for a direct answer about the new tax plan.","clip":1},"wh-equivocate":{"src":"concept:13:words:10:hook","route":"#/word/equivocate","cta":"Open the word card","title":"Remember it · equivocate","body":"To EQUIVOCATE is to speak with TWO EQUAL VOICES—VOC in the middle gives it away."},"wo-equivocate":{"src":"lore:equivocate:0","route":"#/word/equivocate","cta":"Open the word card","title":"Where it comes from · equivocate","body":"Latin aequus = equal + vox = voice"},"wd-pseudonym":{"src":"concept:13:words:15:def","route":"#/word/pseudonym","cta":"Open the word card","title":"pseudonym","roman":"SOO-duh-nihm","body":"a fictitious name used when the person performs a particular social role","clip":1},"wx-pseudonym":{"src":"concept:13:words:15:ex","route":"#/word/pseudonym","cta":"Open the word card","title":"In a sentence · pseudonym","body":"The famous author used a pseudonym so readers wouldn't know her real identity.","clip":1},"wh-pseudonym":{"src":"concept:13:words:15:hook","route":"#/word/pseudonym","cta":"Open the word card","title":"Remember it · pseudonym","body":"A PSEUDONYM is a FALSE NAME — PSEUDO+NYM; think 'Sue Doh Nim' uses a fake name to hide from Sue."},"wo-pseudonym":{"src":"lore:pseudonym:0","route":"#/word/pseudonym","cta":"Open the word card","title":"Where it comes from · pseudonym","body":"Greek pseudos = false + onyma = name"},"wd-pseudoscience":{"src":"concept:13:words:16:def","route":"#/word/pseudoscience","cta":"Open the word card","title":"pseudoscience","roman":"soo-doh-SEYE-uhns","body":"an activity resembling science but based on fallacious assumptions","clip":1},"wx-pseudoscience":{"src":"concept:13:words:16:ex","route":"#/word/pseudoscience","cta":"Open the word card","title":"In a sentence · pseudoscience","body":"The school board voted to remove the textbook chapter that taught astrology as if it were science rather than pseudoscience.","clip":1},"wh-pseudoscience":{"src":"concept:13:words:16:hook","route":"#/word/pseudoscience","cta":"Open the word card","title":"Remember it · pseudoscience","body":"PSEUDOSCIENCE = PSEUDO + SCIENCE — fake science wearing a lab coat; the silent P is as bogus as the field."},"wo-pseudoscience":{"src":"lore:pseudoscience:0","route":"#/word/pseudoscience","cta":"Open the word card","title":"Where it comes from · pseudoscience","body":"Greek pseudos = false + Latin scientia = knowledge"},"li-u117":{"src":"concept:14:concept","route":"#/stop/u117","cta":"Open this stop","title":"Feelings & Emotions — the Four Humors","body":"Medieval medicine believed four bodily fluids controlled personality. This gave English four core emotion words still used today — each with an unusual spelling pattern that spelling bees love."},"lc-u117-0":{"src":"concept:14:cards:0","route":"#/stop/u117","cta":"Open this stop","title":"Feelings & Emotions — the Four Humors · The Four Humors","body":"Blood → sanguine (optimistic). Yellow bile → choleric (quick-tempered). Phlegm → phlegmatic (calm, unemotional). Black bile → melancholy (deeply sad). From a 2,000-year-old medical theory — still the best set of personality adjectives in English."},"lc-u117-1":{"src":"concept:14:cards:1","route":"#/stop/u117","cta":"Open this stop","title":"Feelings & Emotions — the Four Humors · Sanguine & Choleric","body":"Sanguine (SANG-gwin) from Latin sanguis = blood; the silent e at end. Choleric (KOL-er-ik) from Greek khole = bile; ch = /k/ (Greek signal). Blood brought joy; bile brought anger. Opposite types, opposite spelling origins."},"lc-u117-2":{"src":"concept:14:cards:2","route":"#/stop/u117","cta":"Open this stop","title":"Feelings & Emotions — the Four Humors · Phlegmatic — the Hardest Spelling","body":"From Greek phlegma = mucus. Phlegm alone = P-H-L-E-G-M (silent g). Phlegmatic = P-H-L-E-G-M-A-T-I-C (silent g again). Both the ph AND the silent g are Greek signals in one word."},"lc-u117-3":{"src":"concept:14:cards:3","route":"#/stop/u117","cta":"Open this stop","title":"Feelings & Emotions — the Four Humors · Positive Emotion Words","body":"Ebullient (ebullire = boil up) = bubbling with enthusiasm. Effervescent = lively like fizzy bubbles. Exuberant = overflowing with energy. Vivacious (vivax = lively) = attractively animated. Sanguine = optimistically cheerful."},"lc-u117-4":{"src":"concept:14:cards:4","route":"#/stop/u117","cta":"Open this stop","title":"Feelings & Emotions — the Four Humors · Calm & Neutral Emotions","body":"Apathetic (a- + pathos) = without feeling. Stoic (from the Stoa porch in Athens) = endures hardship without complaint. Imperturbable = impossible to upset. Equanimous = steadily even-tempered. Phlegmatic = so calm as to seem indifferent."},"uq-u117-0":{"src":"unit:u117:qs:0","route":"#/stop/u117","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Feelings & Emotions — the Four Humors”?","opts":["Medieval medicine believed four bodily fluids controlled personality.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Feelings & Emotions — the Four Humors”."}},"uq-u117-3":{"src":"unit:u117:qs:3","route":"#/stop/u117","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁ is blood-red — the U-I-N-E at the end spells the color into your veins.” — which word is this hook about?","opts":["sanguine","choleric","phlegmatic","melancholy"],"after":"From “Feelings & Emotions — the Four Humors”."}},"wd-sanguine":{"src":"concept:14:words:0:def","route":"#/word/sanguine","cta":"Open the word card","title":"sanguine","roman":"SA-nggwihn","body":"a blood-red color","clip":1},"wx-sanguine":{"src":"concept:14:words:0:ex","route":"#/word/sanguine","cta":"Open the word card","title":"In a sentence · sanguine","body":"Despite the team's difficult loss in the semifinals, the coach remained sanguine about their chances next season, telling reporters with a calm smile that every setback contains a valuable lesson.","clip":1},"wh-sanguine":{"src":"concept:14:words:0:hook","route":"#/word/sanguine","cta":"Open the word card","title":"Remember it · sanguine","body":"SANGUINE is blood-red — the U-I-N-E at the end spells the color into your veins."},"wd-choleric":{"src":"concept:14:words:1:def","route":"#/word/choleric","cta":"Open the word card","title":"choleric","roman":"KAH-ler-ihk","body":"easily moved to anger; - H.G.Wells","clip":1},"wx-choleric":{"src":"concept:14:words:1:ex","route":"#/word/choleric","cta":"Open the word card","title":"In a sentence · choleric","body":"men of the choleric type take to kicking and smashing","clip":1},"wh-choleric":{"src":"concept:14:words:1:hook","route":"#/word/choleric","cta":"Open the word card","title":"Remember it · choleric","body":"A CHOLERIC person is full of bile — ch + ol + eric, imagine an angry guy named Eric."},"wo-choleric":{"src":"lore:choleric:0","route":"#/word/choleric","cta":"Open the word card","title":"Where it comes from · choleric","body":"Greek khole = bile (bile was thought to cause anger)"},"wd-phlegmatic":{"src":"concept:14:words:2:def","route":"#/word/phlegmatic","cta":"Open the word card","title":"phlegmatic","roman":"f-l-eh-g-m-A-t-ih-k","body":"is not easily excited to action","clip":1},"wx-phlegmatic":{"src":"concept:14:words:2:ex","route":"#/word/phlegmatic","cta":"Open the word card","title":"In a sentence · phlegmatic","body":"a phlegmatic...and certainly undemonstrative man","clip":1},"wh-phlegmatic":{"src":"concept:14:words:2:hook","route":"#/word/phlegmatic","cta":"Open the word card","title":"Remember it · phlegmatic","body":"PHLEGMATIC: the silent PH mirrors how phlegmatic people are — quiet and still, just like the silent letters"},"wo-phlegmatic":{"src":"lore:phlegmatic:0","route":"#/word/phlegmatic","cta":"Open the word card","title":"Where it comes from · phlegmatic","body":"Greek phlegma (flame, phlegm — the cold, moist humor thought to cause calmness)"},"wd-melancholy":{"src":"concept:14:words:3:def","route":"#/word/melancholy","cta":"Open the word card","title":"melancholy","roman":"m-EH-l-uh-n-k-ah-l-ee","body":"is a gloomy state of mind","clip":1},"wx-melancholy":{"src":"concept:14:words:3:ex","route":"#/word/melancholy","cta":"Open the word card","title":"In a sentence · melancholy","body":"growing more melancholy every hour","clip":1},"wh-melancholy":{"src":"concept:14:words:3:hook","route":"#/word/melancholy","cta":"Open the word card","title":"Remember it · melancholy","body":"MELANCHOLY: MELANcholy is not about a MELON — remember black (melan) + bile (choly), not fruit."},"wo-melancholy":{"src":"lore:melancholy:0","route":"#/word/melancholy","cta":"Open the word card","title":"Where it comes from · melancholy","body":"Greek melas = black + khole = bile"},"wd-ebullient":{"src":"concept:14:words:4:def","route":"#/word/ebullient","cta":"Open the word card","title":"ebullient","roman":"ih-BUH-lyuhnt","body":"joyously unrestrained","clip":1},"wx-ebullient":{"src":"concept:14:words:4:ex","route":"#/word/ebullient","cta":"Open the word card","title":"In a sentence · ebullient","body":"The ebullient crowd cheered and danced when their team scored the winning goal in overtime.","clip":1},"wh-ebullient":{"src":"concept:14:words:4:hook","route":"#/word/ebullient","cta":"Open the word card","title":"Remember it · ebullient","body":"An eBULLient person BULLS their way through a room bubbling with joy — double the 'l' like a boiling bubble."},"wo-ebullient":{"src":"lore:ebullient:0","route":"#/word/ebullient","cta":"Open the word card","title":"Where it comes from · ebullient","body":"Latin ebullire = to bubble up (e-=out + bullire=to boil)"},"wd-exuberant":{"src":"concept:14:words:6:def","route":"#/word/exuberant","cta":"Open the word card","title":"exuberant","roman":"ih-GZOO-ber-uhnt","body":"joyously unrestrained","clip":1},"wx-exuberant":{"src":"concept:14:words:6:ex","route":"#/word/exuberant","cta":"Open the word card","title":"In a sentence · exuberant","body":"The exuberant puppy bounded across the yard, leaping into the pile of autumn leaves and scattering them in every colorful direction with joyful abandon.","clip":1},"wh-exuberant":{"src":"concept:14:words:6:hook","route":"#/word/exuberant","cta":"Open the word card","title":"Remember it · exuberant","body":"EXUBERANT ends in -ANT: the exuberant ANT throws the most enthusiastic picnic."},"wo-exuberant":{"src":"lore:exuberant:0","route":"#/word/exuberant","cta":"Open the word card","title":"Where it comes from · exuberant","body":"Latin exuberare = to be abundant, uber = fertile"},"wd-apathetic":{"src":"concept:14:words:8:def","route":"#/word/apathetic","cta":"Open the word card","title":"apathetic","roman":"a-puh-THEH-tihk","body":"showing little or no emotion or animation","clip":1},"wx-apathetic":{"src":"concept:14:words:8:ex","route":"#/word/apathetic","cta":"Open the word card","title":"In a sentence · apathetic","body":"a woman who became active rather than apathetic as she grew older","clip":1},"wh-apathetic":{"src":"concept:14:words:8:hook","route":"#/word/apathetic","cta":"Open the word card","title":"Remember it · apathetic","body":"Someone apathetic has NO PATHOS — the 'path' of feeling is blocked by the 'a' at the front."},"wo-apathetic":{"src":"lore:apathetic:0","route":"#/word/apathetic","cta":"Open the word card","title":"Where it comes from · apathetic","body":"Greek apatheia, from a- = without + pathos = feeling"},"wd-stoic":{"src":"concept:14:words:9:def","route":"#/word/stoic","cta":"Open the word card","title":"stoic","roman":"STOH-ihk","body":"a member of the ancient Greek school of philosophy founded by Zeno","clip":1},"wx-stoic":{"src":"concept:14:words:9:ex","route":"#/word/stoic","cta":"Open the word card","title":"In a sentence · stoic","body":"a Stoic achieves happiness by submission to destiny","clip":1},"wh-stoic":{"src":"concept:14:words:9:hook","route":"#/word/stoic","cta":"Open the word card","title":"Remember it · stoic","body":"A STOIC feels no pain — spelled simply s-t-o-i-c, as calmly as a stoic faces hardship."},"wd-vehement":{"src":"concept:14:words:12:def","route":"#/word/vehement","cta":"Open the word card","title":"vehement","roman":"VEE-uh-muhnt","body":"marked by extreme intensity of emotions or convictions; inclined to react violently; fervid","clip":1},"wx-vehement":{"src":"concept:14:words:12:ex","route":"#/word/vehement","cta":"Open the word card","title":"In a sentence · vehement","body":"The defense attorney delivered a vehement argument, passionately insisting that the evidence was flawed and that her client deserved to walk free from the courtroom that very day.","clip":1},"wh-vehement":{"src":"concept:14:words:12:hook","route":"#/word/vehement","cta":"Open the word card","title":"Remember it · vehement","body":"A VEHEMENT speaker shouts — remember the hidden HE: 'HE is VEHEMENT!'"},"wo-vehement":{"src":"lore:vehement:0","route":"#/word/vehement","cta":"Open the word card","title":"Where it comes from · vehement","body":"Latin vehementem = violent, eager, from vehere = to carry forcefully"},"wd-ardent":{"src":"concept:14:words:13:def","route":"#/word/ardent","cta":"Open the word card","title":"ardent","roman":"AH-rduhnt","body":"characterized by intense emotion","clip":1},"wx-ardent":{"src":"concept:14:words:13:ex","route":"#/word/ardent","cta":"Open the word card","title":"In a sentence · ardent","body":"Maria was such an ardent fan of the local soccer team that she painted her face in team colors, arrived two hours early to every match, and memorized every player's statistics.","clip":1},"wh-ardent":{"src":"concept:14:words:13:hook","route":"#/word/ardent","cta":"Open the word card","title":"Remember it · ardent","body":"An ARDENT fan burns with passion — the fire is in the E: ardENt, not ardAnt."},"wx-fervent":{"src":"concept:14:words:14:ex","route":"#/word/fervent","cta":"Open the word card","title":"In a sentence · fervent","body":"Maya delivered a fervent speech about protecting the local river, her passionate voice rising and falling as she urged every community member to take immediate action.","clip":1},"wh-fervent":{"src":"concept:14:words:14:hook","route":"#/word/fervent","cta":"Open the word card","title":"Remember it · fervent","body":"FervENT not fervANT — think of the INTENSE ENERGY boiling inside, E for Energy in the ending."},"wx-fervid":{"src":"concept:14:words:15:ex","route":"#/word/fervid","cta":"Open the word card","title":"In a sentence · fervid","body":"The young activist delivered a fervid speech about climate change that left the entire audience breathless, moved by the intensity of her passion and the urgency of her message.","clip":1},"wh-fervid":{"src":"concept:14:words:15:hook","route":"#/word/fervid","cta":"Open the word card","title":"Remember it · fervid","body":"FERVid feelings BURN VIDly — think 'vivid' heat inside you."},"wx-impassioned":{"src":"concept:14:words:16:ex","route":"#/word/impassioned","cta":"Open the word card","title":"In a sentence · impassioned","body":"The young activist delivered an impassioned speech at the town hall meeting, her voice trembling with emotion as she pleaded with city officials to protect the local wetlands from industrial development.","clip":1},"wh-impassioned":{"src":"concept:14:words:16:hook","route":"#/word/impassioned","cta":"Open the word card","title":"Remember it · impassioned","body":"An imPASSIONed speech is full of PASSION — you can see passion right inside it."},"wo-impassioned":{"src":"lore:impassioned:0","route":"#/word/impassioned","cta":"Open the word card","title":"Where it comes from · impassioned","body":"Latin passio = suffering, feeling"},"li-u118":{"src":"concept:15:concept","route":"#/stop/u118","cta":"Open this stop","title":"Wisdom & Foolishness — sap / sophos / stult","body":"Latin sapientia = wisdom and Greek sophos = wise generate the intelligence vocabulary. The -acious/-acity cluster gives you character adjectives and their noun twins in one pattern."},"lc-u118-0":{"src":"concept:15:cards:0","route":"#/stop/u118","cta":"Open this stop","title":"Wisdom & Foolishness — sap / sophos / stult · The Wisdom Scale","body":"Omniscient (knows everything) → sagacious (wise from experience) → perspicacious (sharply insightful) → sapient (genuinely wise) → prudent (wisely careful) → obtuse (slow to understand) → fatuous (smugly foolish) → vacuous (empty-headed). One scale, eight vocabulary words."},"lc-u118-1":{"src":"concept:15:cards:1","route":"#/stop/u118","cta":"Open this stop","title":"Wisdom & Foolishness — sap / sophos / stult · The -acious → -acity Pattern","body":"Perspicacious/perspicacity, sagacious/sagacity, tenacious/tenacity, voracious/voracity, audacious/audacity, loquacious/loquacity. The rule is locked: drop -ious, add -ity. One spelling family unlocks twelve words."},"lc-u118-2":{"src":"concept:15:cards:2","route":"#/stop/u118","cta":"Open this stop","title":"Wisdom & Foolishness — sap / sophos / stult · Foolishness Words","body":"Fatuous (fatuus = foolish) = smugly foolish. Vacuous (vacuus = empty) = empty-headed. Obtuse (obtusus = blunt) = slow to understand. Asinine (asinus = donkey) = extremely stupid. Inane = pointlessly silly. Puerile (puer = boy) = childishly silly."},"lc-u118-3":{"src":"concept:15:cards:3","route":"#/stop/u118","cta":"Open this stop","title":"Wisdom & Foolishness — sap / sophos / stult · sophos- (Greek wisdom)","body":"Sophisticated = worldly wise. Sophomore (sophos + moros = fool) = a wise fool — a second-year student who thinks they know everything! Philosophy (philos = love + sophia) = love of wisdom. Sophistry = clever but misleading argument."},"lc-u118-4":{"src":"concept:15:cards:4","route":"#/stop/u118","cta":"Open this stop","title":"Wisdom & Foolishness — sap / sophos / stult · The Knowing Roots","body":"Latin scire = to know: science, omniscient, conscience, prescient (knowing before). Greek gnosis = knowledge: agnostic (without certainty), prognosis (pro- + gnosis = knowing before = forecast), diagnosis (dia- = apart = identifying by analysis)."},"uq-u118-0":{"src":"unit:u118:qs:0","route":"#/stop/u118","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Wisdom & Foolishness — sap / sophos / stult”?","opts":["Latin sapientia = wisdom and Greek sophos = wise generate the intelligence vocabulary.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Wisdom & Foolishness — sap / sophos / stult”."}},"wx-sapient":{"src":"concept:15:words:2:ex","route":"#/word/sapient","cta":"Open the word card","title":"In a sentence · sapient","body":"Village elders offered sapient advice about the harvest, and every word proved true.","clip":1},"wh-sapient":{"src":"concept:15:words:2:hook","route":"#/word/sapient","cta":"Open the word card","title":"Remember it · sapient","body":"SAPIENT — Homo sapiens means 'wise human,' so sapient means wise, just like our species name."},"wd-prudent":{"src":"concept:15:words:4:def","route":"#/word/prudent","cta":"Open the word card","title":"prudent","roman":"PROO-duhnt","body":"careful and sensible; marked by sound judgment","clip":1},"wx-prudent":{"src":"concept:15:words:4:ex","route":"#/word/prudent","cta":"Open the word card","title":"In a sentence · prudent","body":"It was prudent of the hikers to pack extra water and a detailed map before setting out on the long mountain trail, even though the weather forecast had promised a clear and sunny day.","clip":1},"wh-prudent":{"src":"concept:15:words:4:hook","route":"#/word/prudent","cta":"Open the word card","title":"Remember it · prudent","body":"A PRUDENT person is wise—end it with -ENT, not -ANT, just as wisdom is never aNTsy."},"wd-obtuse":{"src":"concept:15:words:5:def","route":"#/word/obtuse","cta":"Open the word card","title":"obtuse","roman":"ah-BTOOS","body":"of an angle; between 90 and 180 degrees","clip":1},"wx-obtuse":{"src":"concept:15:words:5:ex","route":"#/word/obtuse","cta":"Open the word card","title":"In a sentence · obtuse","body":"too obtuse to grasp the implications of his behavior","clip":1},"wh-obtuse":{"src":"concept:15:words:5:hook","route":"#/word/obtuse","cta":"Open the word card","title":"Remember it · obtuse","body":"An obtuse angle is MORE than 90° and a dull person is MORE than slow — both are blunt, spell it ob-TUSE like a blunt fuse!"},"wd-fatuous":{"src":"concept:15:words:6:def","route":"#/word/fatuous","cta":"Open the word card","title":"fatuous","roman":"FA-chuh-wuhs","body":"devoid of intelligence","clip":1},"wx-fatuous":{"src":"concept:15:words:6:ex","route":"#/word/fatuous","cta":"Open the word card","title":"In a sentence · fatuous","body":"His fatuous comment about the moon being made of cheese made everyone in the science class groan.","clip":1},"wh-fatuous":{"src":"concept:15:words:6:hook","route":"#/word/fatuous","cta":"Open the word card","title":"Remember it · fatuous","body":"A FATUOUS remark is FAT with foolishness — no extra E, just pure empty fat."},"wd-vacuous":{"src":"concept:15:words:7:def","route":"#/word/vacuous","cta":"Open the word card","title":"vacuous","roman":"v-A-k-y-oo-uh-s","body":"Completely empty of meaning, substance, or intelligence; lacking serious thought or depth.","clip":1},"wx-vacuous":{"src":"concept:15:words:7:ex","route":"#/word/vacuous","cta":"Open the word card","title":"In a sentence · vacuous","body":"The vacuous reality show offered nothing educational or meaningful, featuring contestants who spent thirty minutes debating which shade of pink best represented their personal brand without ever saying anything remotely interesting or thoughtful.","clip":1},"wh-vacuous":{"src":"concept:15:words:7:hook","route":"#/word/vacuous","cta":"Open the word card","title":"Remember it · vacuous","body":"VACUOUS means full of emptiness—no double-C, just one C: a truly hollow word for hollow minds."},"wo-vacuous":{"src":"lore:vacuous:0","route":"#/word/vacuous","cta":"Open the word card","title":"Where it comes from · vacuous","body":"Latin vacuus = empty"},"wd-asinine":{"src":"concept:15:words:8:def","route":"#/word/asinine","cta":"Open the word card","title":"asinine","roman":"A-suh-neyen","body":"devoid of intelligence","clip":1},"wx-asinine":{"src":"concept:15:words:8:ex","route":"#/word/asinine","cta":"Open the word card","title":"In a sentence · asinine","body":"Everyone in the meeting thought it was asinine to cancel the field trip over such a minor issue.","clip":1},"wh-asinine":{"src":"concept:15:words:8:hook","route":"#/word/asinine","cta":"Open the word card","title":"Remember it · asinine","body":"ASININE has nine letters and refers to acting like a donkey — 'an ASS IN INE stupidity'."},"wd-sophisticated":{"src":"concept:15:words:9:def","route":"#/word/sophisticated","cta":"Open the word card","title":"sophisticated","roman":"suh-FIH-stuh-kay-tihd","body":"make less natural or innocent","clip":1},"wx-sophisticated":{"src":"concept:15:words:9:ex","route":"#/word/sophisticated","cta":"Open the word card","title":"In a sentence · sophisticated","body":"After spending a summer in Paris, she returned with a sophisticated taste for art that impressed even her teachers.","clip":1},"wh-sophisticated":{"src":"concept:15:words:9:hook","route":"#/word/sophisticated","cta":"Open the word card","title":"Remember it · sophisticated","body":"SOPHI-stic-ated: a SOPHIST (wise one) is sophisticated"},"wo-sophisticated":{"src":"lore:sophisticated:0","route":"#/word/sophisticated","cta":"Open the word card","title":"Where it comes from · sophisticated","body":"Greek sophistēs = wise man, from sophos = wise"},"wd-sophomore":{"src":"concept:15:words:10:def","route":"#/word/sophomore","cta":"Open the word card","title":"sophomore","roman":"SAH-fmawr","body":"a second-year undergraduate","clip":1},"wx-sophomore":{"src":"concept:15:words:10:ex","route":"#/word/sophomore","cta":"Open the word card","title":"In a sentence · sophomore","body":"As a sophomore, Delia finally felt comfortable navigating the large high school campus, knowing where every classroom was and understanding the unspoken social rules that had confused her during her first year.","clip":1},"wh-sophomore":{"src":"concept:15:words:10:hook","route":"#/word/sophomore","cta":"Open the word card","title":"Remember it · sophomore","body":"A SOPHOMORE is a 'wise fool'—sopho+MORE: you know MORE but still act foolish, so keep that silent 'o' in sophoMORE."},"wd-sophistry":{"src":"concept:15:words:11:def","route":"#/word/sophistry","cta":"Open the word card","title":"sophistry","roman":"SAW-fih-stree","body":"a deliberately invalid argument displaying ingenuity in reasoning in the hope of deceiving someone","clip":1},"wx-sophistry":{"src":"concept:15:words:11:ex","route":"#/word/sophistry","cta":"Open the word card","title":"In a sentence · sophistry","body":"The debate judge warned that clever sophistry would not substitute for real evidence and honest reasoning.","clip":1},"wh-sophistry":{"src":"concept:15:words:11:hook","route":"#/word/sophistry","cta":"Open the word card","title":"Remember it · sophistry","body":"A SOPHIST tries to TRY to trick you with clever-sounding lies—sophisTRY ends in -TRY, not -TERY."},"wd-agnostic":{"src":"concept:15:words:17:def","route":"#/word/agnostic","cta":"Open the word card","title":"agnostic","roman":"a-GNAH-stihk","body":"someone who is doubtful or noncommittal about something","clip":1},"wx-agnostic":{"src":"concept:15:words:17:ex","route":"#/word/agnostic","cta":"Open the word card","title":"In a sentence · agnostic","body":"My uncle describes himself as an agnostic because he believes it is impossible to know for certain whether any god exists.","clip":1},"wh-agnostic":{"src":"concept:15:words:17:hook","route":"#/word/agnostic","cta":"Open the word card","title":"Remember it · agnostic","body":"An AGNOSTIC is 'a' person who does 'NOT' claim to KNOW — silent 'g' like in 'gnosis.'"},"wo-agnostic":{"src":"lore:agnostic:0","route":"#/word/agnostic","cta":"Open the word card","title":"Where it comes from · agnostic","body":"Greek agnostos = unknown, from a-(not)+gnostos(known)"},"wd-prognosis":{"src":"concept:15:words:18:def","route":"#/word/prognosis","cta":"Open the word card","title":"prognosis","roman":"prah-GNOH-suhs","body":"a prediction about how something (as the weather) will develop","clip":1},"wx-prognosis":{"src":"concept:15:words:18:ex","route":"#/word/prognosis","cta":"Open the word card","title":"In a sentence · prognosis","body":"The doctor gave an encouraging prognosis, saying the patient should fully recover within six weeks.","clip":1},"wh-prognosis":{"src":"concept:15:words:18:hook","route":"#/word/prognosis","cta":"Open the word card","title":"Remember it · prognosis","body":"A proGNOSis is what the doctor KNOWS before the outcome — one 's' in the middle, end in '-sis'."},"wo-prognosis":{"src":"lore:prognosis:0","route":"#/word/prognosis","cta":"Open the word card","title":"Where it comes from · prognosis","body":"Greek pro=before + gignoskein=to know"},"wd-diagnosis":{"src":"concept:15:words:19:def","route":"#/word/diagnosis","cta":"Open the word card","title":"diagnosis","roman":"deye-uh-GNOH-suhs","body":"identifying the nature or cause of some phenomenon","clip":1},"wx-diagnosis":{"src":"concept:15:words:19:ex","route":"#/word/diagnosis","cta":"Open the word card","title":"In a sentence · diagnosis","body":"After weeks of confusing symptoms, the doctor finally delivered a diagnosis that allowed the patient to begin the right treatment.","clip":1},"wh-diagnosis":{"src":"concept:15:words:19:hook","route":"#/word/diagnosis","cta":"Open the word card","title":"Remember it · diagnosis","body":"A diagnosis is KNOWLEDGE (gnosis) gained THROUGH (dia) examination — one S, not two!"},"wo-diagnosis":{"src":"lore:diagnosis:0","route":"#/word/diagnosis","cta":"Open the word card","title":"Where it comes from · diagnosis","body":"Greek diagnosis = discernment, from dia = through + gnosis = knowledge"},"li-u119":{"src":"concept:16:concept","route":"#/stop/u119","cta":"Open this stop","title":"Courage & Fear — aud / fort / tim / phob","body":"Latin audere = to dare, fortis = strong, and timor = fear create an elegant bravery vocabulary. Greek phobos = fear adds the medical compound fear words — all long, all appearing in bees."},"lc-u119-0":{"src":"concept:16:cards:0","route":"#/stop/u119","cta":"Open this stop","title":"Courage & Fear — aud / fort / tim / phob · Courage Root — aud-","body":"Latin audere = to dare. Audacious = daringly bold. Audacity = boldness, sometimes shocking nerve. ⚠️ BEE TRAP: audacious (daring) shares aud- with audible (hearing, from audire) — two different Latin roots with identical prefix. The definition tells you which is which."},"lc-u119-1":{"src":"concept:16:cards:1","route":"#/stop/u119","cta":"Open this stop","title":"Courage & Fear — aud / fort / tim / phob · fort- = Strong","body":"Latin fortis = strong. Fortitude = inner strength. Fortify = make strong. Comfortable (com- + fort) = made strong and at ease together. Effort (ex- + fort) = force pushed outward. Fortissimo (Italian music) = very loud/strong. One root explains a fort, comfort, effort, and a musical term."},"lc-u119-2":{"src":"concept:16:cards:2","route":"#/stop/u119","cta":"Open this stop","title":"Courage & Fear — aud / fort / tim / phob · Fearfulness — tim-","body":"Latin timor = fear. Timid = easily frightened. Timorous = full of trembling fear. Intimidate (in- + timid + -ate) = put fear into someone. ⚠️ Temerity (temere = recklessly) = reckless boldness — confusingly the OPPOSITE of timidity. A classic bee trap."},"lc-u119-3":{"src":"concept:16:cards:3","route":"#/stop/u119","cta":"Open this stop","title":"Courage & Fear — aud / fort / tim / phob · phob- Family (Greek)","body":"Greek phobos = fear. Agoraphobia (agora = marketplace) = fear of open/crowded spaces. Claustrophobia (claustrum = enclosed) = fear of enclosed spaces. Xenophobia (xenos = stranger) = fear of foreigners. Triskaidekaphobia = fear of the number 13 — the longest common fear word."},"lc-u119-4":{"src":"concept:16:cards:4","route":"#/stop/u119","cta":"Open this stop","title":"Courage & Fear — aud / fort / tim / phob · Brave vs Reckless","body":"Valiant = showing genuine courage. Intrepid (in- + trepidus = trembling) = fearless. Dauntless = not daunted. Temerity = reckless boldness (lacks wisdom). Audacity = daring boldness (can be admirable). Knowing the distinction wins vocabulary rounds."},"uq-u119-0":{"src":"unit:u119:qs:0","route":"#/stop/u119","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Courage & Fear — aud / fort / tim / phob”?","opts":["Latin audere = to dare, fortis = strong, and timor = fear create an elegant bravery vocabulary.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Courage & Fear — aud / fort / tim / phob”."}},"uq-u119-3":{"src":"unit:u119:qs:3","route":"#/stop/u119","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁ people DARE to be heard — like a loud AUDIO blast” — which word is this hook about?","opts":["audacious","audacity","fortitude","fortify"],"after":"From “Courage & Fear — aud / fort / tim / phob”."}},"wd-fortitude":{"src":"concept:16:words:2:def","route":"#/word/fortitude","cta":"Open the word card","title":"fortitude","roman":"FAW-rtih-tood","body":"strength of mind that enables one to endure adversity with courage","clip":1},"wx-fortitude":{"src":"concept:16:words:2:ex","route":"#/word/fortitude","cta":"Open the word card","title":"In a sentence · fortitude","body":"It took tremendous fortitude for the young climber to push through the blizzard and reach the summit.","clip":1},"wh-fortitude":{"src":"concept:16:words:2:hook","route":"#/word/fortitude","cta":"Open the word card","title":"Remember it · fortitude","body":"A person with fortITUDE has the ATTITUDE to endure — both end in TUDE."},"wo-fortitude":{"src":"lore:fortitude:0","route":"#/word/fortitude","cta":"Open the word card","title":"Where it comes from · fortitude","body":"Latin fortitudo = strength"},"wd-fortify":{"src":"concept:16:words:3:def","route":"#/word/fortify","cta":"Open the word card","title":"fortify","roman":"FAW-rtih-feye","body":"make strong or stronger","clip":1},"wx-fortify":{"src":"concept:16:words:3:ex","route":"#/word/fortify","cta":"Open the word card","title":"In a sentence · fortify","body":"Warm porridge and boiled eggs fortify us before the long walk to school.","clip":1},"wh-fortify":{"src":"concept:16:words:3:hook","route":"#/word/fortify","cta":"Open the word card","title":"Remember it · fortify","body":"FORTIFY = FORTI + FY — think FORT + I + FY: a fort I will fortiFY with an I not an E."},"wo-fortify":{"src":"lore:fortify:0","route":"#/word/fortify","cta":"Open the word card","title":"Where it comes from · fortify","body":"Latin fortis (strong) + facere (to make) — to make strong."},"wd-comfortable":{"src":"concept:16:words:4:def","route":"#/word/comfortable","cta":"Open the word card","title":"comfortable","roman":"KUH-mfer-tuh-buhl","body":"providing or experiencing physical well-being or relief (`comfy' is informal)","clip":1},"wx-comfortable":{"src":"concept:16:words:4:ex","route":"#/word/comfortable","cta":"Open the word card","title":"In a sentence · comfortable","body":"After hiking through the muddy trail for six exhausting hours, the campers were finally comfortable sitting beside the warm fire, wrapped in dry blankets and sipping hot cocoa.","clip":1},"wh-comfortable":{"src":"concept:16:words:4:hook","route":"#/word/comfortable","cta":"Open the word card","title":"Remember it · comfortable","body":"COMFORTABLE has COMFORT right inside it — if you can spell comfort, just add ABLE."},"wo-comfortable":{"src":"lore:comfortable:0","route":"#/word/comfortable","cta":"Open the word card","title":"Where it comes from · comfortable","body":"Old French confort = to strengthen + Latin -abilis = able to be"},"wd-effort":{"src":"concept:16:words:5:def","route":"#/word/effort","cta":"Open the word card","title":"effort","roman":"EH-fert","body":"earnest and conscientious activity intended to do or accomplish something","clip":1},"wx-effort":{"src":"concept:16:words:5:ex","route":"#/word/effort","cta":"Open the word card","title":"In a sentence · effort","body":"made an effort to cover all the reading material","clip":1},"wh-effort":{"src":"concept:16:words:5:hook","route":"#/word/effort","cta":"Open the word card","title":"Remember it · effort","body":"EFFORT takes FORT-itude — you must be FORT-strong (ef-FORT) to push through the task."},"wd-timid":{"src":"concept:16:words:6:def","route":"#/word/timid","cta":"Open the word card","title":"timid","roman":"TIH-mihd","body":"people who are fearful and cautious","clip":1},"wx-timid":{"src":"concept:16:words:6:ex","route":"#/word/timid","cta":"Open the word card","title":"In a sentence · timid","body":"whitewater rafting is not for the timid","clip":1},"wh-timid":{"src":"concept:16:words:6:hook","route":"#/word/timid","cta":"Open the word card","title":"Remember it · timid","body":"A TIMID mouse hides with just one 'm' — too scared to double up."},"wo-timid":{"src":"lore:timid:0","route":"#/word/timid","cta":"Open the word card","title":"Where it comes from · timid","body":"Latin timidus = fearful, from timere = to fear"},"wd-timorous":{"src":"concept:16:words:7:def","route":"#/word/timorous","cta":"Open the word card","title":"timorous","roman":"TIH-mer-uhs","body":"timid by nature or revealing timidity","clip":1},"wx-timorous":{"src":"concept:16:words:7:ex","route":"#/word/timorous","cta":"Open the word card","title":"In a sentence · timorous","body":"timorous little mouse","clip":1},"wh-timorous":{"src":"concept:16:words:7:hook","route":"#/word/timorous","cta":"Open the word card","title":"Remember it · timorous","body":"A TIMOROUS person is full of TIMOR (fear) — spot the Latin root hiding inside."},"wo-timorous":{"src":"lore:timorous:0","route":"#/word/timorous","cta":"Open the word card","title":"Where it comes from · timorous","body":"Latin timor = fear, from timere = to fear"},"wd-intimidate":{"src":"concept:16:words:8:def","route":"#/word/intimidate","cta":"Open the word card","title":"intimidate","roman":"ih-n-t-IH-m-ih-d-ay-t","body":"to make fearful.","clip":1},"wx-intimidate":{"src":"concept:16:words:8:ex","route":"#/word/intimidate","cta":"Open the word card","title":"In a sentence · intimidate","body":"Her boss intimidates her","clip":1},"wh-intimidate":{"src":"concept:16:words:8:hook","route":"#/word/intimidate","cta":"Open the word card","title":"Remember it · intimidate","body":"To INTIMIDATE someone, you put TIMID in them — you make them timid!"},"wo-intimidate":{"src":"lore:intimidate:0","route":"#/word/intimidate","cta":"Open the word card","title":"Where it comes from · intimidate","body":"Latin timidus = fearful"},"wd-temerity":{"src":"concept:16:words:9:def","route":"#/word/temerity","cta":"Open the word card","title":"temerity","roman":"tuh-MEH-ruh-tee","body":"excessive confidence or boldness; audacious daring, often in the face of danger or opposition","clip":1},"wx-temerity":{"src":"concept:16:words:9:ex","route":"#/word/temerity","cta":"Open the word card","title":"In a sentence · temerity","body":"Priya had the temerity to challenge the reigning chess champion despite having played for only six months.","clip":1},"wh-temerity":{"src":"concept:16:words:9:hook","route":"#/word/temerity","cta":"Open the word card","title":"Remember it · temerity","body":"teMERity — MERE boldness pushed too far"},"wo-temerity":{"src":"lore:temerity:0","route":"#/word/temerity","cta":"Open the word card","title":"Where it comes from · temerity","body":"Latin temeritas = rashness, from temere = blindly, rashly"},"wd-agoraphobia":{"src":"concept:16:words:10:def","route":"#/word/agoraphobia","cta":"Open the word card","title":"agoraphobia","roman":"uh-gaw-ruh-FOH-bee-uh","body":"a morbid fear of open spaces or of being alone in a public place where escape might be difficult","clip":1},"wx-agoraphobia":{"src":"concept:16:words:10:ex","route":"#/word/agoraphobia","cta":"Open the word card","title":"In a sentence · agoraphobia","body":"Because of her agoraphobia, the woman rarely left her apartment and felt her heart race at the thought of walking through a crowded mall.","clip":1},"wh-agoraphobia":{"src":"concept:16:words:10:hook","route":"#/word/agoraphobia","cta":"Open the word card","title":"Remember it · agoraphobia","body":"AGORA (marketplace) + PHOBIA — fear of the open marketplace"},"wo-agoraphobia":{"src":"lore:agoraphobia:0","route":"#/word/agoraphobia","cta":"Open the word card","title":"Where it comes from · agoraphobia","body":"Greek agora = marketplace + phobos = fear"},"wd-claustrophobia":{"src":"concept:16:words:11:def","route":"#/word/claustrophobia","cta":"Open the word card","title":"claustrophobia","roman":"klaw-struh-FOH-bee-uh","body":"a morbid fear of being closed in a confined space","clip":1},"wx-claustrophobia":{"src":"concept:16:words:11:ex","route":"#/word/claustrophobia","cta":"Open the word card","title":"In a sentence · claustrophobia","body":"Zara's claustrophobia made riding the crowded elevator feel like a terrifying adventure every single morning.","clip":1},"wh-claustrophobia":{"src":"concept:16:words:11:hook","route":"#/word/claustrophobia","cta":"Open the word card","title":"Remember it · claustrophobia","body":"CLAUS(TRO) = locked door + PHOBIA = fear: fear of locked spaces"},"wo-claustrophobia":{"src":"lore:claustrophobia:0","route":"#/word/claustrophobia","cta":"Open the word card","title":"Where it comes from · claustrophobia","body":"Latin claustrum = enclosed space, bolt + Greek phobos = fear"},"wd-xenophobia":{"src":"concept:16:words:12:def","route":"#/word/xenophobia","cta":"Open the word card","title":"xenophobia","roman":"zeh-nuh-FOH-bee-uh","body":"a fear of foreigners or strangers","clip":1},"wx-xenophobia":{"src":"concept:16:words:12:ex","route":"#/word/xenophobia","cta":"Open the word card","title":"In a sentence · xenophobia","body":"The community worked hard to overcome xenophobia by hosting cultural festivals that celebrated their diverse neighbors.","clip":1},"wh-xenophobia":{"src":"concept:16:words:12:hook","route":"#/word/xenophobia","cta":"Open the word card","title":"Remember it · xenophobia","body":"XENO means stranger, PHOBIA means fear — xenophobia is fear of strangers, spelled just as it sounds: x-e-n-o-p-h-o-b-i-a."},"wo-xenophobia":{"src":"lore:xenophobia:0","route":"#/word/xenophobia","cta":"Open the word card","title":"Where it comes from · xenophobia","body":"Greek xenos = stranger + phobos = fear"},"wd-triskaidekaphobia":{"src":"concept:16:words:13:def","route":"#/word/triskaidekaphobia","cta":"Open the word card","title":"triskaidekaphobia","roman":"tris-ky-dek-uh-FOH-bee-uh","body":"is a fear of the number 13","clip":1},"wx-triskaidekaphobia":{"src":"concept:16:words:13:ex","route":"#/word/triskaidekaphobia","cta":"Open the word card","title":"In a sentence · triskaidekaphobia","body":"Because of his triskaidekaphobia, he refused to stay in room 13 at any hotel he ever visited.","clip":1},"wh-triskaidekaphobia":{"src":"concept:16:words:13:hook","route":"#/word/triskaidekaphobia","cta":"Open the word card","title":"Remember it · triskaidekaphobia","body":"TRISKAIDEKA spells out 3+and+10=13—fear the KAI in the middle!"},"wo-triskaidekaphobia":{"src":"lore:triskaidekaphobia:0","route":"#/word/triskaidekaphobia","cta":"Open the word card","title":"Where it comes from · triskaidekaphobia","body":"Greek triskaideka = thirteen + phobos = fear"},"wd-valiant":{"src":"concept:16:words:14:def","route":"#/word/valiant","cta":"Open the word card","title":"valiant","roman":"VA-lyuhnt","body":"having or showing valor","clip":1},"wx-valiant":{"src":"concept:16:words:14:ex","route":"#/word/valiant","cta":"Open the word card","title":"In a sentence · valiant","body":"The valiant soldier crawled through enemy fire to rescue his wounded comrade.","clip":1},"wh-valiant":{"src":"concept:16:words:14:hook","route":"#/word/valiant","cta":"Open the word card","title":"Remember it · valiant","body":"VALIANT — VALOR and VALIANT share the same root: strength."},"wo-valiant":{"src":"lore:valiant:0","route":"#/word/valiant","cta":"Open the word card","title":"Where it comes from · valiant","body":"Old French vaillant, from Latin valere = to be strong"},"wx-intrepid":{"src":"concept:16:words:15:ex","route":"#/word/intrepid","cta":"Open the word card","title":"In a sentence · intrepid","body":"The intrepid young journalist traveled alone through four war zones to document the stories of civilians whose lives had been upended by a conflict the rest of the world had largely ignored.","clip":1},"wh-intrepid":{"src":"concept:16:words:15:hook","route":"#/word/intrepid","cta":"Open the word card","title":"Remember it · intrepid","body":"An intrepid hero doesn't TREMBLE — trepid means trembling, and in- means NOT, so no shaking!"},"wo-intrepid":{"src":"lore:intrepid:0","route":"#/word/intrepid","cta":"Open the word card","title":"Where it comes from · intrepid","body":"Latin in = not + trepidus = alarmed, trembling"},"wx-dauntless":{"src":"concept:16:words:16:ex","route":"#/word/dauntless","cta":"Open the word card","title":"In a sentence · dauntless","body":"The dauntless young climber pressed on through howling wind and driving sleet, refusing to turn back even as the mountain's summit disappeared behind a wall of dark, churning storm clouds.","clip":1},"wh-dauntless":{"src":"concept:16:words:16:hook","route":"#/word/dauntless","cta":"Open the word card","title":"Remember it · dauntless","body":"Dauntless heroes have LESS fear — the '-less' at the end means without daunting!"},"wo-dauntless":{"src":"lore:dauntless:0","route":"#/word/dauntless","cta":"Open the word card","title":"Where it comes from · dauntless","body":"Latin domitare = to tame"},"li-u120":{"src":"concept:17:concept","route":"#/stop/u120","cta":"Open this stop","title":"Kindness & Cruelty — ben / mal / clem","body":"Latin bene = well/good and malus = bad/evil are the fundamental moral roots in English. Swapping the prefix flips the meaning — know one side of every pair and you know both."},"lc-u120-0":{"src":"concept:17:cards:0","route":"#/stop/u120","cta":"Open this stop","title":"Kindness & Cruelty — ben / mal / clem · The ben-/bene- Root (good)","body":"Latin bene = well. Benevolent (bene + velle = wish well) = wishing good for others. Benefactor (bene + facere) = one who does good. Benign (bene + genus = kind) = gentle and harmless. Benediction (bene + dicere) = a spoken blessing."},"lc-u120-1":{"src":"concept:17:cards:1","route":"#/stop/u120","cta":"Open this stop","title":"Kindness & Cruelty — ben / mal / clem · The mal- Root (bad)","body":"Latin malus = bad. Malevolent = wishing harm. Malfeasance (mal- + facere = do wrong) = official wrongdoing. Malicious = intending harm. Malignant = growing harmfully. Maladroit (mal- + French adroit = skillful) = clumsy. The prefix paints everything it touches as bad."},"lc-u120-2":{"src":"concept:17:cards:2","route":"#/stop/u120","cta":"Open this stop","title":"Kindness & Cruelty — ben / mal / clem · The Perfect Pairs","body":"Benevolent ↔ malevolent. Beneficent ↔ maleficent. Benign ↔ malignant. Benediction ↔ malediction. These are structural opposites — swap ben- for mal- and the meaning reverses. In a bee, knowing one word of each pair gives you the other for free."},"lc-u120-3":{"src":"concept:17:cards:3","route":"#/stop/u120","cta":"Open this stop","title":"Kindness & Cruelty — ben / mal / clem · clem- = Merciful","body":"Latin clemens = mild, merciful. Clemency = merciful treatment. Clement = mild (weather or character). Inclement (in- + clement) = harsh, stormy. Clemency appears in legal vocabulary: appeal for clemency = asking for a lighter sentence."},"lc-u120-4":{"src":"concept:17:cards:4","route":"#/stop/u120","cta":"Open this stop","title":"Kindness & Cruelty — ben / mal / clem · Malaise & Malaria — Etymology Reveals History","body":"Malaise (mal- + French aise = ease) = general feeling of being unwell. Malaria (mal- + Italian aria = air) = bad air — Italians believed this disease came from bad swamp air before mosquitoes were discovered. Etymology IS history."},"uq-u120-0":{"src":"unit:u120:qs:0","route":"#/stop/u120","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Kindness & Cruelty — ben / mal / clem”?","opts":["Latin bene = well/good and malus = bad/evil are the fundamental moral roots in English.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Kindness & Cruelty — ben / mal / clem”."}},"uq-u120-3":{"src":"unit:u120:qs:3","route":"#/stop/u120","cta":"Open this stop","title":"Whose hook?","play":{"q":"“A ▁▁▁ person wishes you WELL — bene means 'well' in Latin, spelled B-E-N-E.” — which word is this hook about?","opts":["benevolent","benefactor","benign","benediction"],"after":"From “Kindness & Cruelty — ben / mal / clem”."}},"wd-benevolent":{"src":"concept:17:words:0:def","route":"#/word/benevolent","cta":"Open the word card","title":"benevolent","roman":"buh-NEH-vuh-luhnt","body":"intending or showing kindness","clip":1},"wx-benevolent":{"src":"concept:17:words:0:ex","route":"#/word/benevolent","cta":"Open the word card","title":"In a sentence · benevolent","body":"a benevolent society","clip":1},"wh-benevolent":{"src":"concept:17:words:0:hook","route":"#/word/benevolent","cta":"Open the word card","title":"Remember it · benevolent","body":"A BENEvolent person wishes you WELL — bene means 'well' in Latin, spelled B-E-N-E."},"wd-benefactor":{"src":"concept:17:words:1:def","route":"#/word/benefactor","cta":"Open the word card","title":"benefactor","roman":"BEH-nuh-fa-kter","body":"a person who helps people or institutions (especially with financial help)","clip":1},"wx-benefactor":{"src":"concept:17:words:1:ex","route":"#/word/benefactor","cta":"Open the word card","title":"In a sentence · benefactor","body":"An anonymous benefactor donated enough money to rebuild the school library after it was destroyed in the flood.","clip":1},"wh-benefactor":{"src":"concept:17:words:1:hook","route":"#/word/benefactor","cta":"Open the word card","title":"Remember it · benefactor","body":"A benefACTOR is an ACTOR who does good deeds — remember the -OR ending like 'actor.'"},"wo-benefactor":{"src":"lore:benefactor:0","route":"#/word/benefactor","cta":"Open the word card","title":"Where it comes from · benefactor","body":"Latin bene = well + factor = doer (from facere = to do)"},"wd-benign":{"src":"concept:17:words:2:def","route":"#/word/benign","cta":"Open the word card","title":"benign","roman":"b-ih-n-AY-n","body":"is having a kindly disposition","clip":1},"wx-benign":{"src":"concept:17:words:2:ex","route":"#/word/benign","cta":"Open the word card","title":"In a sentence · benign","body":"The doctor reassured the worried family that the small growth was completely benign, explaining that it posed no threat to the patient's health and required no further treatment whatsoever.","clip":1},"wh-benign":{"src":"concept:17:words:2:hook","route":"#/word/benign","cta":"Open the word card","title":"Remember it · benign","body":"beNIGN ends in -IGN like 'sign' — a benign tumor is a good SIGN, spelled G-N."},"wo-benign":{"src":"lore:benign:0","route":"#/word/benign","cta":"Open the word card","title":"Where it comes from · benign","body":"Latin benignus = kind, from bene = well + gignere = to beget"},"wd-beneficent":{"src":"concept:17:words:4:def","route":"#/word/beneficent","cta":"Open the word card","title":"beneficent","roman":"beh-nuh-FIH-shuhnt","body":"doing or producing good","clip":1},"wx-beneficent":{"src":"concept:17:words:4:ex","route":"#/word/beneficent","cta":"Open the word card","title":"In a sentence · beneficent","body":"The beneficent billionaire donated millions of dollars to build new schools and hospitals in impoverished communities around the world.","clip":1},"wh-beneficent":{"src":"concept:17:words:4:hook","route":"#/word/beneficent","cta":"Open the word card","title":"Remember it · beneficent","body":"BENE (good) + FICENT — bene-FICENT does good things, like magnificent but good"},"wo-beneficent":{"src":"lore:beneficent:0","route":"#/word/beneficent","cta":"Open the word card","title":"Where it comes from · beneficent","body":"Latin bene = well + facere = to do"},"wd-clemency":{"src":"concept:17:words:10:def","route":"#/word/clemency","cta":"Open the word card","title":"clemency","roman":"KLEH-muh-nsee","body":"mercy and lenience shown toward someone it is within one's power to punish; also mildness of weather","clip":1},"wx-clemency":{"src":"concept:17:words:10:ex","route":"#/word/clemency","cta":"Open the word card","title":"In a sentence · clemency","body":"The defendant's lawyer pleaded for clemency, arguing that her client had already suffered enough and deserved a second chance.","clip":1},"wh-clemency":{"src":"concept:17:words:10:hook","route":"#/word/clemency","cta":"Open the word card","title":"Remember it · clemency","body":"CLEMENCY: think of a CLEMENT (mild) judge — CLEMENt+CY = mercy."},"wo-clemency":{"src":"lore:clemency:0","route":"#/word/clemency","cta":"Open the word card","title":"Where it comes from · clemency","body":"Latin clemens = mild, merciful"},"wd-clement":{"src":"concept:17:words:11:def","route":"#/word/clement","cta":"Open the word card","title":"clement","roman":"KLEH-muhnt","body":"(of weather or climate) physically mild","clip":1},"wx-clement":{"src":"concept:17:words:11:ex","route":"#/word/clement","cta":"Open the word card","title":"In a sentence · clement","body":"The farmers were grateful for the clement weather during harvest season, as the mild temperatures and gentle breezes made it easy to work long hours in the fields.","clip":1},"wh-clement":{"src":"concept:17:words:11:hook","route":"#/word/clement","cta":"Open the word card","title":"Remember it · clement","body":"CLEMENT weather is mild — think of a KIND person named Clem who is gentle and MILD-mannered."},"wd-inclement":{"src":"concept:17:words:12:def","route":"#/word/inclement","cta":"Open the word card","title":"inclement","roman":"ih-NKLEH-muhnt","body":"(of weather or climate) severe","clip":1},"wx-inclement":{"src":"concept:17:words:12:ex","route":"#/word/inclement","cta":"Open the word card","title":"In a sentence · inclement","body":"the harsh sentence of an inclement judge","clip":1},"wh-inclement":{"src":"concept:17:words:12:hook","route":"#/word/inclement","cta":"Open the word card","title":"Remember it · inclement","body":"Inclement weather is not CLEMENT (mild) — the opposite of clemency from the sky."},"wo-inclement":{"src":"lore:inclement:0","route":"#/word/inclement","cta":"Open the word card","title":"Where it comes from · inclement","body":"Latin inclemens = harsh, unmerciful"},"li-u121":{"src":"concept:18:concept","route":"#/stop/u121","cta":"Open this stop","title":"Social & Solitary — greg / anthrop / soci / mis","body":"Latin grex = flock and Greek anthropos = human being create vocabulary about how people relate to society. These are some of the richest theme words in English."},"lc-u121-0":{"src":"concept:18:cards:0","route":"#/stop/u121","cta":"Open this stop","title":"Social & Solitary — greg / anthrop / soci / mis · The greg- Root (flock)","body":"Latin grex = flock. Gregarious = loves being in groups like sheep. Congregate (con- + greg-) = flock together. Segregate (se- = apart) = separate from the flock. Aggregate (ad- + greg-) = gathered into a total. ⚠️ Egregious (e- = out of + greg-) = standing out from the flock — outstandingly BAD."},"lc-u121-1":{"src":"concept:18:cards:1","route":"#/stop/u121","cta":"Open this stop","title":"Social & Solitary — greg / anthrop / soci / mis · mis- = Hatred (Greek misos)","body":"Greek misos = hatred. Misanthrope (misos + anthropos) = hates humanity. Misogynist (misos + gyne = woman) = hates women. Misogamist (misos + gamos = marriage) = hates marriage. ⚠️ This mis- is GREEK (hatred) — completely different from LATIN mis- (wrongly). Same spelling, entirely different origin."},"lc-u121-2":{"src":"concept:18:cards:2","route":"#/stop/u121","cta":"Open this stop","title":"Social & Solitary — greg / anthrop / soci / mis · anthrop- = Human Being","body":"Greek anthropos = human. Anthropology = study of humans. Philanthropist (philos = love + anthropos) = lover of humanity. Misanthrope = hater of humanity. Anthropomorphic = giving human form to non-humans. Anthropocentric = placing humans at the center of everything."},"lc-u121-3":{"src":"concept:18:cards:3","route":"#/stop/u121","cta":"Open this stop","title":"Social & Solitary — greg / anthrop / soci / mis · soci- = Companion","body":"Latin socius = companion. Sociable = friendly and sociable. Associate = join as a companion. Dissociate = separate from. Convivial (con- + vivere = live together) = friendly and lively at a gathering. Affable (af- + fari = speak to) = easy and pleasant to talk with."},"lc-u121-4":{"src":"concept:18:cards:4","route":"#/stop/u121","cta":"Open this stop","title":"Social & Solitary — greg / anthrop / soci / mis · The Loner Words","body":"Misanthrope = hates people. Solitary (solus = alone) = prefers being alone. Recluse = withdraws from society. Hermit (Greek eremos = desert) = lives alone. Anchorite = withdraws for religious seclusion. Note: a loner avoids people; a misanthrope hates them — critically different."},"uq-u121-0":{"src":"unit:u121:qs:0","route":"#/stop/u121","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Social & Solitary — greg / anthrop / soci / mis”?","opts":["Latin grex = flock and Greek anthropos = human being create vocabulary about how people relate to society.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Social & Solitary — greg / anthrop / soci / mis”."}},"uq-u121-3":{"src":"unit:u121:qs:3","route":"#/stop/u121","cta":"Open this stop","title":"Whose hook?","play":{"q":"“A ▁▁▁ person flocks with others — greg = flock in Latin, so spell it g-r-e-g, then -arious like 'various.'” — which word is this hook about?","opts":["gregarious","egregious","congregate","segregate"],"after":"From “Social & Solitary — greg / anthrop / soci / mis”."}},"wd-gregarious":{"src":"concept:18:words:0:def","route":"#/word/gregarious","cta":"Open the word card","title":"gregarious","roman":"gruh-GEH-ree-uhs","body":"(of animals) tending to form a group with others of the same species","clip":1},"wx-gregarious":{"src":"concept:18:words:0:ex","route":"#/word/gregarious","cta":"Open the word card","title":"In a sentence · gregarious","body":"gregarious bird species","clip":1},"wh-gregarious":{"src":"concept:18:words:0:hook","route":"#/word/gregarious","cta":"Open the word card","title":"Remember it · gregarious","body":"A GREGARIOUS person flocks with others — greg = flock in Latin, so spell it g-r-e-g, then -arious like 'various.'"},"wo-gregarious":{"src":"lore:gregarious:0","route":"#/word/gregarious","cta":"Open the word card","title":"Where it comes from · gregarious","body":"Latin grex/gregis = flock + -arious = tending to"},"wd-egregious":{"src":"concept:18:words:1:def","route":"#/word/egregious","cta":"Open the word card","title":"egregious","roman":"ih-g-r-EE-j-uh-s","body":"is extraordinary in some bad way","clip":1},"wx-egregious":{"src":"concept:18:words:1:ex","route":"#/word/egregious","cta":"Open the word card","title":"In a sentence · egregious","body":"The referee made such an egregious error during the championship game that even fans from the winning team shook their heads in disbelief and demanded an instant replay review.","clip":1},"wh-egregious":{"src":"concept:18:words:1:hook","route":"#/word/egregious","cta":"Open the word card","title":"Remember it · egregious","body":"EGREGIOUS has GREG in the middle — imagine Greg the bad sheep who stood so far OUT from the flock his error was egregious."},"wo-egregious":{"src":"lore:egregious:0","route":"#/word/egregious","cta":"Open the word card","title":"Where it comes from · egregious","body":"Latin e = out + grex/gregis = flock, standing out from the flock"},"wd-congregate":{"src":"concept:18:words:2:def","route":"#/word/congregate","cta":"Open the word card","title":"congregate","roman":"KAH-nggruh-gayt","body":"come together, usually for a purpose","clip":1},"wx-congregate":{"src":"concept:18:words:2:ex","route":"#/word/congregate","cta":"Open the word card","title":"In a sentence · congregate","body":"The crowds congregated in front of the Vatican on Christmas Eve","clip":1},"wh-congregate":{"src":"concept:18:words:2:hook","route":"#/word/congregate","cta":"Open the word card","title":"Remember it · congregate","body":"People conGREGate in a GREAT group — GREG leads the flock!"},"wo-congregate":{"src":"lore:congregate:0","route":"#/word/congregate","cta":"Open the word card","title":"Where it comes from · congregate","body":"Latin congregare = to gather together"},"wd-segregate":{"src":"concept:18:words:3:def","route":"#/word/segregate","cta":"Open the word card","title":"segregate","roman":"SEH-gruh-gayt","body":"someone who is or has been segregated","clip":1},"wx-segregate":{"src":"concept:18:words:3:ex","route":"#/word/segregate","cta":"Open the word card","title":"In a sentence · segregate","body":"This neighborhood is segregated","clip":1},"wh-segregate":{"src":"concept:18:words:3:hook","route":"#/word/segregate","cta":"Open the word card","title":"Remember it · segregate","body":"To SEGREGATE is to separate the flock — SE+GREGATE, think 'Greg ATE alone, apart from the group.'"},"wo-segregate":{"src":"lore:segregate:0","route":"#/word/segregate","cta":"Open the word card","title":"Where it comes from · segregate","body":"Latin se- = apart + grex/gregis = flock"},"wd-aggregate":{"src":"concept:18:words:4:def","route":"#/word/aggregate","cta":"Open the word card","title":"aggregate","roman":"A-gruh-guht","body":"the whole amount","clip":1},"wx-aggregate":{"src":"concept:18:words:4:ex","route":"#/word/aggregate","cta":"Open the word card","title":"In a sentence · aggregate","body":"In the aggregate, the students raised over two thousand dollars for the school's new science lab.","clip":1},"wh-aggregate":{"src":"concept:18:words:4:hook","route":"#/word/aggregate","cta":"Open the word card","title":"Remember it · aggregate","body":"AGGREGATE gathers a flock — DOUBLE G + GREG (like congregate) — the whole herd AGGREGATES."},"wo-aggregate":{"src":"lore:aggregate:0","route":"#/word/aggregate","cta":"Open the word card","title":"Where it comes from · aggregate","body":"Latin aggregare = to add to a flock (ad- + grex flock)"},"wd-misogynist":{"src":"concept:18:words:6:def","route":"#/word/misogynist","cta":"Open the word card","title":"misogynist","roman":"MIH-zuh-jih-nihst","body":"a misanthrope who dislikes women in particular","clip":1},"wx-misogynist":{"src":"concept:18:words:6:ex","route":"#/word/misogynist","cta":"Open the word card","title":"In a sentence · misogynist","body":"The reformer challenged the misogynist who believed women should have no voice in government or education.","clip":1},"wh-misogynist":{"src":"concept:18:words:6:hook","route":"#/word/misogynist","cta":"Open the word card","title":"Remember it · misogynist","body":"A misoGYNIST hates women — end with -IST like a specialist in hatred, not -yst."},"wd-misogamist":{"src":"concept:18:words:7:def","route":"#/word/misogamist","cta":"Open the word card","title":"misogamist","roman":"mih-SOG-uh-mist","body":"a person who hates marriage","clip":1},"wx-misogamist":{"src":"concept:18:words:7:ex","route":"#/word/misogamist","cta":"Open the word card","title":"In a sentence · misogamist","body":"The grumpy misogamist refused to wed.","clip":1},"wh-misogamist":{"src":"concept:18:words:7:hook","route":"#/word/misogamist","cta":"Open the word card","title":"Remember it · misogamist","body":"from Greek misos 'hatred' + gamos 'marriage'"},"wd-anthropology":{"src":"concept:18:words:8:def","route":"#/word/anthropology","cta":"Open the word card","title":"anthropology","roman":"a-nthruh-PAH-luh-jee","body":"the social science that studies the origins and social relationships of human beings","clip":1},"wx-anthropology":{"src":"concept:18:words:8:ex","route":"#/word/anthropology","cta":"Open the word card","title":"In a sentence · anthropology","body":"Her fascination with ancient cultures led her to major in anthropology at the university.","clip":1},"wh-anthropology":{"src":"concept:18:words:8:hook","route":"#/word/anthropology","cta":"Open the word card","title":"Remember it · anthropology","body":"ANTHRO-PO-LOGY: 'a POLO player studying humans' — remember the hidden POLO in anthroPoLOgy."},"wo-anthropology":{"src":"lore:anthropology:0","route":"#/word/anthropology","cta":"Open the word card","title":"Where it comes from · anthropology","body":"Greek anthropos = human being + logos = study"},"wd-anthropocentric":{"src":"concept:18:words:11:def","route":"#/word/anthropocentric","cta":"Open the word card","title":"anthropocentric","roman":"a-nthruh-puh-SEH-ntrihk","body":"human-centered","clip":1},"wx-anthropocentric":{"src":"concept:18:words:11:ex","route":"#/word/anthropocentric","cta":"Open the word card","title":"In a sentence · anthropocentric","body":"our anthropocentric view of the world","clip":1},"wh-anthropocentric":{"src":"concept:18:words:11:hook","route":"#/word/anthropocentric","cta":"Open the word card","title":"Remember it · anthropocentric","body":"ANTHROPO-CENTRIC: humans (anthropo) at the CENTER (centri) — spell it like you're centering yourself: no K at the end!"},"wo-anthropocentric":{"src":"lore:anthropocentric:0","route":"#/word/anthropocentric","cta":"Open the word card","title":"Where it comes from · anthropocentric","body":"Greek anthropos = human + kentron = center"},"wd-sociable":{"src":"concept:18:words:12:def","route":"#/word/sociable","cta":"Open the word card","title":"sociable","roman":"SOH-shuh-buhl","body":"a party of people assembled to promote sociability and communal activity","clip":1},"wx-sociable":{"src":"concept:18:words:12:ex","route":"#/word/sociable","cta":"Open the word card","title":"In a sentence · sociable","body":"Because she was naturally sociable and genuinely curious about people, Maya made friends easily at her new school, striking up conversations with classmates during lunch on her very first day.","clip":1},"wh-sociable":{"src":"concept:18:words:12:hook","route":"#/word/sociable","cta":"Open the word card","title":"Remember it · sociable","body":"A SOCIABLE person is SOCI-ABLE to make friends—drop the E from society before adding ABLE."},"wo-sociable":{"src":"lore:sociable:0","route":"#/word/sociable","cta":"Open the word card","title":"Where it comes from · sociable","body":"Latin sociabilis = fit for companionship, from socius = companion"},"wd-associate":{"src":"concept:18:words:13:def","route":"#/word/associate","cta":"Open the word card","title":"associate","roman":"uh-SOH-see-uht","body":"a person who joins with others in some activity or endeavor","clip":1},"wx-associate":{"src":"concept:18:words:13:ex","route":"#/word/associate","cta":"Open the word card","title":"In a sentence · associate","body":"he had to consult his associate before continuing","clip":1},"wh-associate":{"src":"concept:18:words:13:hook","route":"#/word/associate","cta":"Open the word card","title":"Remember it · associate","body":"An ASSOCIATE is a SOCIAL companion — find SOC-I inside, then add -ATE at the end."},"wo-associate":{"src":"lore:associate:0","route":"#/word/associate","cta":"Open the word card","title":"Where it comes from · associate","body":"Latin associare = to join to (socius = companion)"},"wd-affable":{"src":"concept:18:words:15:def","route":"#/word/affable","cta":"Open the word card","title":"affable","roman":"A-fuh-buhl","body":"friendly, easy to talk to, and pleasant in manner","clip":1},"wx-affable":{"src":"concept:18:words:15:ex","route":"#/word/affable","cta":"Open the word card","title":"In a sentence · affable","body":"Our new neighbor was so affable that within minutes of meeting her, we felt as if we had known her for years.","clip":1},"wh-affable":{"src":"concept:18:words:15:hook","route":"#/word/affable","cta":"Open the word card","title":"Remember it · affable","body":"AFfable people are FABulous to talk to — 'FAB' is right in the middle"},"wo-affable":{"src":"lore:affable:0","route":"#/word/affable","cta":"Open the word card","title":"Where it comes from · affable","body":"Latin 'affabilis' = ad (to) + fari (to speak) + -bilis (capable of)"},"wd-recluse":{"src":"concept:18:words:16:def","route":"#/word/recluse","cta":"Open the word card","title":"recluse","roman":"rih-KLOOS","body":"one who lives in solitude","clip":1},"wx-recluse":{"src":"concept:18:words:16:ex","route":"#/word/recluse","cta":"Open the word card","title":"In a sentence · recluse","body":"After years of fame, the retired actress became a recluse who rarely left her mountain cabin.","clip":1},"wh-recluse":{"src":"concept:18:words:16:hook","route":"#/word/recluse","cta":"Open the word card","title":"Remember it · recluse","body":"A recluse is CLOSED off (re-CLUSE) from the world."},"wo-recluse":{"src":"lore:recluse:0","route":"#/word/recluse","cta":"Open the word card","title":"Where it comes from · recluse","body":"Old French reclus, from Latin recludere = to shut away (re- + claudere = to close)"},"wd-hermit":{"src":"concept:18:words:17:def","route":"#/word/hermit","cta":"Open the word card","title":"hermit","roman":"HUR-muht","body":"one retired from society for religious reasons","clip":1},"wx-hermit":{"src":"concept:18:words:17:ex","route":"#/word/hermit","cta":"Open the word card","title":"In a sentence · hermit","body":"The old hermit lived alone in a cave on the mountainside, spending his days in prayer and quiet contemplation.","clip":1},"wh-hermit":{"src":"concept:18:words:17:hook","route":"#/word/hermit","cta":"Open the word card","title":"Remember it · hermit","body":"A HERMIT lives alone with only one T for company."},"li-u122":{"src":"concept:100:concept","route":"#/stop/u122","cta":"Open this stop","title":"Words About Lying & Deception (Rhetorical Terms)","body":"Rhetorical vocabulary describes the techniques of persuasion, deception, and argument. From Aristotle through modern debate, these terms appear in championship bees and are built from Greek and Latin roots."},"lc-u122-0":{"src":"concept:100:cards:0","route":"#/stop/u122","cta":"Open this stop","title":"Words About Lying & Deception (Rhetorical Terms) · Deception Techniques","body":"Prevarication (pre- + varicare = straddle) = evasive speech. Equivocation (equi- + vox = equal voice) = deliberately ambiguous language. Dissimulation (dis- + simulare = pretend) = concealing true feelings. Obfuscation (ob- + fuscare = to darken) = deliberately making things unclear."},"lc-u122-1":{"src":"concept:100:cards:1","route":"#/stop/u122","cta":"Open this stop","title":"Words About Lying & Deception (Rhetorical Terms) · Rhetorical Figures — Saying by Not Saying","body":"Apophasis (apo- = away + phasis = speech) = mentioning something by saying you will not mention it (\"I won't mention his criminal record...\"). Litotes (litos = plain) = understatement by negation (\"not bad\" = very good). Meiosis (meioun = to lessen) = deliberate understatement."},"lc-u122-2":{"src":"concept:100:cards:2","route":"#/stop/u122","cta":"Open this stop","title":"Words About Lying & Deception (Rhetorical Terms) · Figures of Emphasis","body":"Anaphora (ana- = back + phora = carrying) = repetition at the start of successive clauses. Epistrophe (epi- + strephein = turn) = repetition at the end of clauses."},"lc-u122-3":{"src":"concept:100:cards:3","route":"#/stop/u122","cta":"Open this stop","title":"Words About Lying & Deception (Rhetorical Terms) · Logical Fallacies","body":"Sophistry = clever but misleading argument. Solecism (Soloi = a Greek colony with bad Greek) = a grammatical error or social blunder. Malapropism = using the wrong word for a similar-sounding one. Pleonasm (pleon = more) = using more words than necessary (\"free gift,\" \"ATM machine\")."},"lc-u122-4":{"src":"concept:100:cards:4","route":"#/stop/u122","cta":"Open this stop","title":"Words About Lying & Deception (Rhetorical Terms) · High-Value Bee Rhetorical Words","body":"Apophasis = A-P-O-P-H-A-S-I-S (-ph- Greek signal). Chiasmus = C-H-I-A-S-M-U-S (-ch- = /k/). Zeugma = Z-E-U-G-M-A (-eu- diphthong). Tmesis (tmesis = cutting) = inserting a word inside another word (\"what-SO-ever\") = T-M-E-S-I-S (starts with tm- — unusual cluster)."},"uq-u122-0":{"src":"unit:u122:qs:0","route":"#/stop/u122","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Words About Lying & Deception (Rhetorical Terms)”?","opts":["Rhetorical vocabulary describes the techniques of persuasion, deception, and argument.","The most notoriously irregular spelling pattern in English: -ough represents six distinct sounds with no sound-based rule for which applies.","Latin de- removes, reverses, takes down, or completely intensifies.","Latin/Old English mis- = wrongly, badly, or astray."],"after":"From “Words About Lying & Deception (Rhetorical Terms)”."}},"uq-u122-3":{"src":"unit:u122:qs:3","route":"#/stop/u122","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁ contains a VARIATION of the truth — remember VARI and -ation.” — which word is this hook about?","opts":["prevarication","equivocation","dissimulation","obfuscation"],"after":"From “Words About Lying & Deception (Rhetorical Terms)”."}},"wd-prevarication":{"src":"concept:100:words:0:def","route":"#/word/prevarication","cta":"Open the word card","title":"prevarication","roman":"pruh-veh-ruh-KAY-shuhn","body":"a statement that deviates from or perverts the truth","clip":1},"wx-prevarication":{"src":"concept:100:words:0:ex","route":"#/word/prevarication","cta":"Open the word card","title":"In a sentence · prevarication","body":"The judge grew impatient with the witness's prevarication and demanded a direct, honest answer to the question.","clip":1},"wh-prevarication":{"src":"concept:100:words:0:hook","route":"#/word/prevarication","cta":"Open the word card","title":"Remember it · prevarication","body":"PreVARIcation contains a VARIATION of the truth — remember VARI and -ation."},"wo-prevarication":{"src":"lore:prevarication:0","route":"#/word/prevarication","cta":"Open the word card","title":"Where it comes from · prevarication","body":"Latin praevaricari = to straddle, deviate"},"wd-equivocation":{"src":"concept:100:words:1:def","route":"#/word/equivocation","cta":"Open the word card","title":"equivocation","roman":"ih-kwih-vuh-KAY-shuhn","body":"a statement that is not literally false but that cleverly avoids an unpleasant truth","clip":1},"wx-equivocation":{"src":"concept:100:words:1:ex","route":"#/word/equivocation","cta":"Open the word card","title":"In a sentence · equivocation","body":"The politician's equivocation on the tax question frustrated voters who wanted a clear yes or no.","clip":1},"wh-equivocation":{"src":"concept:100:words:1:hook","route":"#/word/equivocation","cta":"Open the word card","title":"Remember it · equivocation","body":"EQUIVOCATION is a VOCal trick of equal deception—V-O-C sits right in the middle."},"wd-dissimulation":{"src":"concept:100:words:2:def","route":"#/word/dissimulation","cta":"Open the word card","title":"dissimulation","roman":"dih-sim-yoo-LAY-shun","body":"the act of deceiving","clip":1},"wx-dissimulation":{"src":"concept:100:words:2:ex","route":"#/word/dissimulation","cta":"Open the word card","title":"In a sentence · dissimulation","body":"The spy's dissimulation was so perfect that even his closest friends suspected nothing.","clip":1},"wh-dissimulation":{"src":"concept:100:words:2:hook","route":"#/word/dissimulation","cta":"Open the word card","title":"Remember it · dissimulation","body":"DIS-SIMUL-ATION: SIMUL like simulate — simulating false feelings to deceive."},"wd-dissembling":{"src":"concept:100:words:4:def","route":"#/word/dissembling","cta":"Open the word card","title":"dissembling","roman":"dih-SEH-mblihng","body":"pretending with intention to deceive","clip":1}});
